/**
 * Main entry point for the CodeYourPCB viewer application
 * Integrates WASM engine, rendering, and user interaction
 */

import './theme/colors.css';
import { themeManager } from './theme/theme-manager';
import { loadWasm, isWasmLoaded, type PcbEngine } from './wasm';
import type { BoardSnapshot, ViolationInfo } from './types';
import { createViewport, fitBoard, screenToWorld } from './viewport';
import { render, type RenderState } from './renderer';
import { setupInteraction, type InteractionState } from './interaction';
import { createRoutingState, cancelRoute, flipLayer, type RoutingState } from './routing';
import { createLayerVisibility } from './layers';
import { createFilePicker, setupDropZone, readFileAsText } from './file-picker';
import { openFile, saveFile } from './file-access';
import { isDesktop, initDesktop } from './desktop';
import { encodeViewState, decodeViewState } from './url-state';

// WebSocket server URL for hot reload
// Dynamic: if accessing via dev1.flightcore.pl, use dev2.flightcore.pl for WS
function getWsUrl(): string {
  const host = window.location.hostname;
  if (host === 'dev1.flightcore.pl') {
    return 'wss://dev2.flightcore.pl';
  }
  // Local development
  return 'ws://localhost:4322';
}
const WS_URL = getWsUrl();

/**
 * WebSocket message types from the dev server
 */
interface WsMessage {
  type: string;
  file?: string;
  content?: string;
  timestamp?: number;
  output?: string;
  error?: string;
  sesContent?: string | null;
  routesContent?: string | null;
  pass?: number;
  routed?: number;
  unrouted?: number;
}

/**
 * WebSocket connection interface for two-way communication with dev server
 */
interface WsConnection {
  send(message: object): void;
  isConnected(): boolean;
}

/**
 * Callbacks for various WebSocket events
 */
interface WsCallbacks {
  onReload: (content: string, file: string) => void;
  onRouteStart?: () => void;
  onRouteProgress?: (output: string) => void;
  onRouteComplete?: (sesContent: string | null, routesContent: string | null) => void;
  onRouteError?: (error: string) => void;
}

/**
 * Connect to the WebSocket server for hot reload and routing.
 * Automatically reconnects on disconnect.
 */
function connectWebSocket(callbacks: WsCallbacks): WsConnection {
  let ws: WebSocket | null = null;
  let connected = false;

  function connect(): void {
    ws = new WebSocket(WS_URL);

    ws.onopen = () => {
      console.log('[WS] Connected');
      connected = true;
    };

    ws.onmessage = (event) => {
      try {
        const msg: WsMessage = JSON.parse(event.data);
        console.log(`[WS] Received: ${msg.type}`);

        switch (msg.type) {
          case 'init':
          case 'reload':
            if (msg.content && msg.file) {
              callbacks.onReload(msg.content, msg.file);
            }
            break;
          case 'route-start':
            callbacks.onRouteStart?.();
            break;
          case 'route-progress':
            callbacks.onRouteProgress?.(msg.output || '');
            break;
          case 'route-complete':
            callbacks.onRouteComplete?.(msg.sesContent || null, msg.routesContent || null);
            break;
          case 'route-error':
            callbacks.onRouteError?.(msg.error || 'Unknown routing error');
            break;
        }
      } catch (err) {
        console.error('[WS] Message parse error:', err);
      }
    };

    ws.onclose = () => {
      console.log('[WS] Disconnected, reconnecting in 2s...');
      connected = false;
      setTimeout(connect, 2000);
    };

    ws.onerror = () => {
      // Error is handled by onclose
    };
  }

  connect();

  return {
    send(message: object): void {
      if (ws && connected) {
        ws.send(JSON.stringify(message));
      } else {
        console.warn('[WS] Cannot send, not connected');
      }
    },
    isConnected(): boolean {
      return connected;
    }
  };
}

// Note: Test data removed. Use examples/routing-test.cypcb and examples/routing-test.ses via file picker.

/**
 * Initialize the PCB viewer application
 */
async function init(): Promise<void> {
  const statusText = document.getElementById('status-text')!;
  const errorBadge = document.getElementById('error-badge')!;
  const errorCountEl = document.getElementById('error-count')!;
  const errorPanel = document.getElementById('error-panel')!;
  const errorList = document.getElementById('error-list')!;
  const errorPanelClose = document.getElementById('error-panel-close')!;
  const canvas = document.getElementById('pcb-canvas') as HTMLCanvasElement;
  const container = document.getElementById('canvas-container')!;
  const coordsEl = document.getElementById('coords')!;
  const topLayerCb = document.getElementById('layer-top') as HTMLInputElement;
  const bottomLayerCb = document.getElementById('layer-bottom') as HTMLInputElement;
  const ratsnestCb = document.getElementById('layer-ratsnest') as HTMLInputElement;
  const routeBtn = document.getElementById('route-btn') as HTMLButtonElement;
  const cancelRouteBtn = document.getElementById('cancel-route-btn') as HTMLButtonElement;
  const autoRouteCb = document.getElementById('auto-route') as HTMLInputElement;
  const routingStatus = document.getElementById('routing-status')!;
  const routingProgress = document.getElementById('routing-progress')!;
  const openBtn = document.getElementById('open-btn') as HTMLButtonElement;
  // @ts-ignore - Used conditionally in web-only block (line 1001-1002)
  const shareBtn = document.getElementById('share-btn') as HTMLButtonElement;
  const themeToggle = document.getElementById('theme-toggle') as HTMLButtonElement;
  const themeIcon = document.getElementById('theme-icon')!;
  const editorToggleBtn = document.getElementById('editor-toggle') as HTMLButtonElement;
  const fitBtn = document.getElementById('fit-btn') as HTMLButtonElement;
  const view3dBtn = document.getElementById('view-3d-btn') as HTMLButtonElement;
  const editorContainer = document.getElementById('editor-container')!

  const ctx = canvas.getContext('2d')!;

  // Routing state
  let isRouting = false;
  let currentFilePath: string | null = null;

  // File handle for save-in-place (File System Access API)
  let currentFileHandle: FileSystemFileHandle | null = null;

  /**
   * Update error badge with violation count
   */
  function updateErrorBadge(violations: ViolationInfo[]): void {
    if (violations.length > 0) {
      errorCountEl.textContent = String(violations.length);
      errorBadge.classList.remove('hidden');
    } else {
      errorBadge.classList.add('hidden');
      errorPanel.classList.add('hidden');
    }
  }

  // State
  let snapshot: BoardSnapshot | null = null;
  let viewport = createViewport(canvas.width, canvas.height);
  let layers = createLayerVisibility();
  let selectedRefdes: string | null = null;
  let dirty = true;
  let lastLoadedSource: string | null = null;
  let showRatsnest = true;
  let colorByNet = true;
  let selectedTraceId: number | null = null;
  let hoveredTraceId: number | null = null;
  let labelPosition: { x: number; y: number } | null = null;
  let routingState: RoutingState = createRoutingState();

  // 3D view state
  let is3DActive = false;
  let renderer3d: import('./renderer3d').Renderer3D | null = null;

  // Resize handler
  function resize(): void {
    canvas.width = container.clientWidth;
    canvas.height = container.clientHeight;
    viewport = {
      ...viewport,
      width: canvas.width,
      height: canvas.height,
    };
    dirty = true;
  }
  resize();
  window.addEventListener('resize', resize);

  // Layer checkbox handlers — update both 2D and 3D views
  topLayerCb.addEventListener('change', () => {
    layers = {
      ...layers,
      topCopper: topLayerCb.checked,
    };
    dirty = true;
    if (is3DActive && renderer3d) {
      renderer3d.updateLayerVisibility(layers);
    }
  });
  bottomLayerCb.addEventListener('change', () => {
    layers = {
      ...layers,
      bottomCopper: bottomLayerCb.checked,
    };
    dirty = true;
    if (is3DActive && renderer3d) {
      renderer3d.updateLayerVisibility(layers);
    }
  });
  ratsnestCb.addEventListener('change', () => {
    showRatsnest = ratsnestCb.checked;
    dirty = true;
  });

  // Load WASM
  statusText.textContent = 'Loading WASM...';
  let engine: PcbEngine;
  try {
    engine = await loadWasm();
  } catch (err) {
    console.error('WASM load failed:', err);
    statusText.textContent = `WASM Error: ${err}`;
    return;
  }

  const usingWasm = isWasmLoaded();

  // Subscribe to theme changes to trigger canvas re-render + 3D background sync
  themeManager.subscribe(() => {
    dirty = true;
    if (is3DActive && renderer3d) {
      const style = getComputedStyle(document.documentElement);
      const bgColor = style.getPropertyValue('--bg-canvas').trim() || '#1a1a2e';
      renderer3d.setBackground(bgColor);
    }
  });

  // Theme toggle
  function updateThemeIcon(): void {
    const theme = themeManager.getTheme();
    switch (theme) {
      case 'light':
        themeIcon.textContent = '☀️';
        themeToggle.title = 'Theme: Light (click to switch)';
        break;
      case 'dark':
        themeIcon.textContent = '🌙';
        themeToggle.title = 'Theme: Dark (click to switch)';
        break;
      case 'auto':
        themeIcon.textContent = '🔄';
        themeToggle.title = 'Theme: Auto (click to switch)';
        break;
    }
  }

  themeToggle.addEventListener('click', () => {
    const current = themeManager.getTheme();
    // Cycle: light → dark → auto → light
    const next = current === 'light' ? 'dark' : current === 'dark' ? 'auto' : 'light';
    themeManager.setTheme(next);
    updateThemeIcon();
  });

  // Also update icon when OS theme changes (relevant in auto mode)
  themeManager.subscribe(() => {
    updateThemeIcon();
  });

  updateThemeIcon();

  // Monaco editor setup
  let editorInstance: any = null;
  let editorReady = false;
  let suppressSync = false; // Prevent circular updates when setting editor content programmatically
  const { initEditor, toggleEditorPanel, getMonacoModule } = await import('./editor/editor-panel');
  const { updateDiagnostics } = await import('./editor/lsp-bridge');

  /**
   * Setup editor-to-board sync with debounce
   * When editor content changes, parse and update the board viewer
   */
  function setupEditorSync(editor: any): void {
    let debounceTimer: number | null = null;

    editor.onDidChangeModelContent(() => {
      // Skip sync if content was set programmatically (file load, hot reload)
      if (suppressSync) {
        return;
      }

      // Debounce for 300ms
      if (debounceTimer !== null) {
        clearTimeout(debounceTimer);
      }

      debounceTimer = window.setTimeout(() => {
        const content = editor.getValue();
        console.log('[Editor] Content changed, reloading board...');

        // Parse and update board
        const errors = engine.load_source(content);
        if (errors) {
          console.warn('[Editor] Parse errors:', errors);
        }

        // Update snapshot
        snapshot = engine.get_snapshot();

        // Update inline diagnostics (LSP bridge)
        const monaco = getMonacoModule();
        if (monaco && editorInstance) {
          updateDiagnostics(monaco, editorInstance, errors, snapshot.violations || []);
        }

        // Update error badge
        if (snapshot.violations) {
          updateErrorBadge(snapshot.violations);
        }

        // Track as loaded source
        lastLoadedSource = content;

        // Mark as dirty for re-render
        dirty = true;

        debounceTimer = null;
      }, 300);
    });

    console.log('[Editor] Sync wired up with 300ms debounce');
  }

  // Fit board to viewport button
  fitBtn.addEventListener('click', () => {
    if (snapshot?.board) {
      viewport = fitBoard(viewport, snapshot.board.width_nm, snapshot.board.height_nm);
      interactionState.viewport = viewport;
      dirty = true;
    }
  });

  // 3D view toggle
  view3dBtn.addEventListener('click', async () => {
    if (!is3DActive) {
      // Switch to 3D
      if (!renderer3d) {
        try {
          const { Renderer3D } = await import('./renderer3d');
          renderer3d = new Renderer3D();
          renderer3d.init(container);
        } catch (e) {
          console.error('[3D] WebGL not available', e);
          statusText.textContent = 'WebGL not available';
          return;
        }
      }

      // Hide 2D canvas, show 3D
      canvas.style.display = 'none';
      is3DActive = true;
      view3dBtn.classList.add('active');

      // Update board in 3D
      if (snapshot) {
        renderer3d.updateBoard(snapshot, layers);
      }
    } else {
      // Switch back to 2D
      is3DActive = false;
      view3dBtn.classList.remove('active');

      // Show 2D canvas, dispose 3D
      canvas.style.display = '';
      if (renderer3d) {
        renderer3d.dispose();
        renderer3d = null;
      }

      dirty = true; // Force 2D re-render
    }
  });

  // Editor toggle button handler
  editorToggleBtn.addEventListener('click', async () => {
    // Lazy-load editor on first toggle
    if (!editorReady) {
      console.log('[Editor] Initializing Monaco editor...');
      editorInstance = await initEditor(editorContainer);

      // Set initial content if a file is loaded
      if (lastLoadedSource) {
        suppressSync = true;
        editorInstance.setValue(lastLoadedSource);
        suppressSync = false;
      }

      // Wire up editor-to-board sync
      setupEditorSync(editorInstance);

      editorReady = true;
      console.log('[Editor] Monaco editor ready');
    }
    toggleEditorPanel();
    // Trigger canvas resize
    resize();
  });

  // Apply URL state if present (shared URL)
  const urlState = decodeViewState();
  let hasUrlState = urlState !== null;
  if (urlState) {
    // Apply viewport state from URL
    viewport = {
      ...viewport,
      centerX: urlState.panX,
      centerY: urlState.panY,
      scale: urlState.zoom,
    };

    // Apply layer visibility from URL
    const layersFromUrl = urlState.layers;
    topLayerCb.checked = layersFromUrl.includes('top');
    bottomLayerCb.checked = layersFromUrl.includes('bottom');
    ratsnestCb.checked = layersFromUrl.includes('ratsnest');
    layers = {
      topCopper: topLayerCb.checked,
      bottomCopper: bottomLayerCb.checked,
    };
    showRatsnest = ratsnestCb.checked;

    console.log('[URL State] Applied shared view state:', urlState);
  }

  // Start with empty state - user will open a file
  snapshot = engine.get_snapshot();
  currentFilePath = null;
  statusText.textContent = usingWasm ? 'Ready (WASM) - Open a file' : 'Ready (Mock) - Open a file';

  // Interaction setup (must be defined before handleFileLoad which uses it)
  const interactionState: InteractionState = {
    viewport,
    isPanning: false,
    lastX: 0,
    lastY: 0,
    dirty: false,
    snapshot,
    selectedTraceId: null,
    hoveredTraceId: null,
    onSelect: (x_nm, y_nm) => {
      // Query engine for component at point
      const hits = engine.query_point(Math.round(x_nm), Math.round(y_nm));
      if (hits && hits.length > 0) {
        selectedRefdes = hits[0];
        console.log('Selected:', selectedRefdes);
        // Show selected in status
        const comp = snapshot?.components.find(c => c.refdes === selectedRefdes);
        if (comp) {
          statusText.textContent = `Selected: ${comp.refdes} (${comp.value})`;
        }
      } else {
        selectedRefdes = null;
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }
      dirty = true;
    },
    onViewportChange: (vp) => {
      viewport = vp;
      interactionState.viewport = vp;
    },
    onTraceSelect: (traceId, screenX, screenY) => {
      selectedTraceId = traceId;
      if (traceId != null) {
        // Convert client coords to canvas-relative for label positioning
        const rect = canvas.getBoundingClientRect();
        labelPosition = { x: screenX - rect.left, y: screenY - rect.top };
        // Show trace info in status bar
        const trace = snapshot?.traces?.find(t => t.id === traceId);
        if (trace) {
          const widthMm = (trace.width / 1_000_000).toFixed(2);
          statusText.textContent = `Trace: ${trace.net_name} (${widthMm}mm, ${trace.layer})`;
        }
      } else {
        labelPosition = null;
        selectedRefdes = null;
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }
      dirty = true;
    },
    onTraceHover: (traceId) => {
      hoveredTraceId = traceId;
      dirty = true;
    },
    routing: routingState,
    engine,
    onRoutingChange: (newRouting: RoutingState) => {
      routingState = newRouting;
      interactionState.routing = newRouting;
      // Update snapshot after mutations (route complete changes trace list)
      if (newRouting.mode === 'idle' && snapshot) {
        snapshot = engine.get_snapshot();
        interactionState.snapshot = snapshot;
      }
      dirty = true;
    },
  };

  setupInteraction(canvas, interactionState);

  // Expose debug render state for programmatic inspection
  (window as any).__renderState = {
    get selectedTraceId() { return selectedTraceId; },
    get hoveredTraceId() { return hoveredTraceId; },
    get colorByNet() { return colorByNet; },
  };

  // Expose routing state debug surface
  (window as any).__routingState = {
    get mode() { return routingState.mode; },
    get anchorPoint() { return routingState.anchorPoint; },
    get snapAngle() { return routingState.snapAngle; },
    get netName() { return routingState.netName; },
    get currentLayer() { return routingState.currentLayer; },
    get committedSegments() { return routingState.committedSegments.length; },
    get drcViolationCount() { return routingState.drcViolations.length; },
    get previewSegment() { return routingState.previewSegment; },
  };

  /**
   * Handle loading a file (.cypcb or .ses) from file picker or drag-drop
   */
  async function handleFileLoad(file: File): Promise<void> {
    const ext = file.name.toLowerCase().split('.').pop();

    try {
      const content = await readFileAsText(file);

      if (ext === 'cypcb') {
        // Load new board
        const errors = engine.load_source(content);
        if (errors) {
          console.warn('Parse errors:', errors);
        }

        // Track loaded source for save operations
        lastLoadedSource = content;

        // Get new snapshot and fit board
        snapshot = engine.get_snapshot();

        // Update editor content if initialized
        if (editorReady && editorInstance) {
          suppressSync = true;
          editorInstance.setValue(content);
          suppressSync = false;

          // Update inline diagnostics
          const monaco = getMonacoModule();
          if (monaco) {
            updateDiagnostics(monaco, editorInstance, errors, snapshot.violations || []);
          }
        }

        // Update current file path for routing
        currentFilePath = file.name;

        if (snapshot.board) {
          viewport = fitBoard(viewport, snapshot.board.width_nm, snapshot.board.height_nm);
          interactionState.viewport = viewport;
        }

        // Update error badge
        if (snapshot.violations) {
          updateErrorBadge(snapshot.violations);
        }

        // Show status
        const errorCount = errors ? errors.split('\n').filter(Boolean).length : 0;
        statusText.textContent = errorCount > 0
          ? `Loaded ${file.name} (${errorCount} warnings)`
          : `Loaded ${file.name}`;

        dirty = true;

      } else if (ext === 'ses') {
        // Check if board is loaded
        if (!snapshot?.board) {
          statusText.textContent = 'Load a .cypcb file first';
          return;
        }

        // Load routes
        engine.load_routes(content);
        snapshot = engine.get_snapshot();

        statusText.textContent = `Loaded routes from ${file.name}`;
        dirty = true;

      } else {
        statusText.textContent = `Unknown file type: .${ext}`;
      }
    } catch (err) {
      console.error('File load error:', err);
      statusText.textContent = `Error loading ${file.name}`;
    }
  }

  // File picker setup (kept for drag-drop only)
  const filePicker = createFilePicker('.cypcb,.ses', handleFileLoad);

  // Open button - use File System Access API on web, keep file picker for desktop
  openBtn.addEventListener('click', async () => {
    if (isDesktop()) {
      // Desktop uses its own file dialog via Tauri IPC
      filePicker.click();
    } else {
      // Web uses File System Access API with fallback
      const result = await openFile();
      if (result) {
        // Store handle for save-in-place
        currentFileHandle = result.handle;
        currentFilePath = result.name;

        // Parse the content as if it was a file load
        const ext = result.name.toLowerCase().split('.').pop();

        if (ext === 'cypcb') {
          // Load new board
          const errors = engine.load_source(result.content);
          if (errors) {
            console.warn('Parse errors:', errors);
          }

          // Track loaded source for save operations
          lastLoadedSource = result.content;

          // Get new snapshot and fit board
          snapshot = engine.get_snapshot();

          // Update editor content if initialized
          if (editorReady && editorInstance) {
            suppressSync = true;
            editorInstance.setValue(result.content);
            suppressSync = false;

            // Update inline diagnostics
            const monaco = getMonacoModule();
            if (monaco) {
              updateDiagnostics(monaco, editorInstance, errors, snapshot.violations || []);
            }
          }

          if (snapshot.board) {
            viewport = fitBoard(viewport, snapshot.board.width_nm, snapshot.board.height_nm);
            interactionState.viewport = viewport;
          }

          // Update error badge
          if (snapshot.violations) {
            updateErrorBadge(snapshot.violations);
          }

          // Show status
          const errorCount = errors ? errors.split('\n').filter(Boolean).length : 0;
          statusText.textContent = errorCount > 0
            ? `Loaded ${result.name} (${errorCount} warnings)`
            : `Loaded ${result.name}`;

          dirty = true;

        } else if (ext === 'ses') {
          // Check if board is loaded
          if (!snapshot?.board) {
            statusText.textContent = 'Load a .cypcb file first';
            return;
          }

          // Load routes
          engine.load_routes(result.content);
          snapshot = engine.get_snapshot();

          statusText.textContent = `Loaded routes from ${result.name}`;
          dirty = true;

        } else {
          statusText.textContent = `Unknown file type: .${ext}`;
        }
      }
    }
  });

  // Drag-drop setup
  setupDropZone(container, handleFileLoad);

  /**
   * Populate the error list with current violations
   */
  function populateErrorList(): void {
    if (!snapshot?.violations) {
      errorList.innerHTML = '<div class="error-item">No errors</div>';
      return;
    }

    errorList.innerHTML = snapshot.violations.map((v, i) => `
      <div class="error-item" data-index="${i}">
        <span class="error-kind">[${v.kind}]</span>
        <span class="error-message">${v.message}</span>
      </div>
    `).join('');

    // Add click handlers for zoom-to-location
    errorList.querySelectorAll('.error-item').forEach(el => {
      el.addEventListener('click', () => {
        const idx = parseInt(el.getAttribute('data-index')!, 10);
        const violation = snapshot!.violations[idx];
        zoomToLocation(violation.x_nm, violation.y_nm);
      });
    });
  }

  /**
   * Zoom viewport to center on a specific location
   */
  function zoomToLocation(x_nm: number, y_nm: number): void {
    // Zoom to fit a 10mm x 10mm area around the point
    const margin = 5_000_000; // 5mm in nm
    viewport = {
      ...viewport,
      centerX: x_nm,
      centerY: y_nm,
      scale: Math.min(viewport.width, viewport.height) / (margin * 2),
    };
    interactionState.viewport = viewport;
    dirty = true;
  }

  // Error badge click - toggle error panel
  errorBadge.addEventListener('click', () => {
    errorPanel.classList.toggle('hidden');
    if (!errorPanel.classList.contains('hidden')) {
      populateErrorList();
    }
  });

  // Close button for error panel
  errorPanelClose.addEventListener('click', () => {
    errorPanel.classList.add('hidden');
  });

  // Coordinate display on mouse move + update label position for selected trace
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const sx = e.clientX - rect.left;
    const sy = e.clientY - rect.top;
    const [worldX, worldY] = screenToWorld(viewport, sx, sy);
    // Convert to mm for display
    const xMm = (worldX / 1_000_000).toFixed(2);
    const yMm = (worldY / 1_000_000).toFixed(2);
    coordsEl.textContent = `(${xMm}, ${yMm}) mm`;

    // Track label position when a trace is selected
    if (selectedTraceId != null) {
      labelPosition = { x: sx, y: sy };
      dirty = true;
    }
  });

  canvas.addEventListener('mouseleave', () => {
    coordsEl.textContent = '';
  });

  // Visibility state
  const showViolations = true;

  // Render loop
  function frame(): void {
    // Skip 2D rendering when 3D mode is active
    if (!is3DActive && (dirty || interactionState.dirty)) {
      // Keep interaction state snapshot in sync
      interactionState.snapshot = snapshot;

      const renderState: RenderState = {
        snapshot,
        viewport,
        layers,
        selectedRefdes,
        showViolations,
        showRatsnest,
        colorByNet,
        selectedTraceId,
        hoveredTraceId,
        labelPosition,
        routing: routingState.mode === 'routing' ? routingState : null,
      };
      render(ctx, renderState);
      dirty = false;
      interactionState.dirty = false;
    }
    requestAnimationFrame(frame);
  }
  frame();

  // Hot reload handler - preserves viewport and selection
  function reload(content: string, _file: string): void {
    // Save current state
    const savedViewport = { ...viewport };
    const savedSelection = selectedRefdes;

    // Parse new content
    const errors = engine.load_source(content);
    if (errors) {
      console.warn('[HotReload] Parse warnings:', errors);
    }

    // Track loaded source for save operations
    lastLoadedSource = content;

    snapshot = engine.get_snapshot();

    // Update editor content if initialized
    if (editorReady && editorInstance) {
      suppressSync = true;
      editorInstance.setValue(content);
      suppressSync = false;

      // Update inline diagnostics
      const monaco = getMonacoModule();
      if (monaco) {
        updateDiagnostics(monaco, editorInstance, errors, snapshot.violations || []);
      }
    }

    console.log('[HotReload] Reloaded snapshot:', snapshot);

    // Restore viewport — but fit board on first load (default viewport)
    const isDefaultViewport = savedViewport.centerX === 0 && savedViewport.centerY === 0;
    if (isDefaultViewport && snapshot.board) {
      viewport = fitBoard(savedViewport, snapshot.board.width_nm, snapshot.board.height_nm);
    } else {
      viewport = savedViewport;
    }
    interactionState.viewport = viewport;

    // Restore selection if component still exists
    if (savedSelection && snapshot.components.some(c => c.refdes === savedSelection)) {
      selectedRefdes = savedSelection;
    } else {
      selectedRefdes = null;
    }

    // Show "Reloaded" status briefly
    const parseErrorCount = errors ? errors.split('\n').filter(Boolean).length : 0;
    statusText.textContent = parseErrorCount > 0 ? `Reloaded (${parseErrorCount} warnings)` : 'Reloaded';

    // Update error badge with new violations
    if (snapshot.violations) {
      updateErrorBadge(snapshot.violations);
    }

    // After 1.5s, show normal status
    setTimeout(() => {
      if (selectedRefdes && snapshot) {
        const comp = snapshot.components.find(c => c.refdes === selectedRefdes);
        if (comp) {
          statusText.textContent = `Selected: ${comp.refdes} (${comp.value})`;
        }
      } else {
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }
    }, 1500);

    // Trigger re-render
    dirty = true;
  }

  // ========================================================================
  // Routing Integration
  // ========================================================================

  /**
   * Autorouter progress state for UI updates
   */
  interface AutorouteUiState {
    isRouting: boolean;
    pass: number;
    routed: number;
    unrouted: number;
    elapsed: number;
  }

  /**
   * Update UI to reflect autorouter state
   */
  function updateRoutingUI(state: AutorouteUiState): void {
    if (state.isRouting) {
      routeBtn.disabled = true;
      routeBtn.classList.add('routing');
      routeBtn.textContent = 'Routing...';
      cancelRouteBtn.classList.remove('hidden');
      routingStatus.classList.remove('hidden');
      routingProgress.textContent = `Pass ${state.pass}: ${state.routed} routed, ${state.unrouted} unrouted (${state.elapsed}s)`;
    } else {
      routeBtn.disabled = false;
      routeBtn.classList.remove('routing');
      routeBtn.textContent = 'Route';
      cancelRouteBtn.classList.add('hidden');
      routingStatus.classList.add('hidden');
    }
  }

  // WebSocket connection (initialized later)
  let wsConnection: WsConnection | null = null;
  let routingStartTime = 0;

  /**
   * Trigger routing via WebSocket to dev server.
   * The server runs the CLI route command and streams progress.
   */
  async function triggerRouting(): Promise<void> {
    if (isRouting || !currentFilePath) {
      console.log('[Routing] Cannot start routing: already routing or no file loaded');
      return;
    }

    if (!wsConnection || !wsConnection.isConnected()) {
      console.log('[Routing] WebSocket not connected, cannot route');
      statusText.textContent = 'Error: Not connected to dev server';
      return;
    }

    isRouting = true;
    routingStartTime = Date.now();

    updateRoutingUI({
      isRouting: true,
      pass: 0,
      routed: 0,
      unrouted: 0,
      elapsed: 0,
    });

    console.log('[Routing] Starting routing for:', currentFilePath);
    statusText.textContent = 'Routing...';

    // Send route request to dev server
    wsConnection.send({
      type: 'route',
      file: currentFilePath,
    });
  }

  /**
   * Handle routing completion from WebSocket
   */
  function handleRouteComplete(sesContent: string | null, _routesContent: string | null): void {
    isRouting = false;
    const elapsed = Math.round((Date.now() - routingStartTime) / 1000);
    updateRoutingUI({ isRouting: false, pass: 0, routed: 0, unrouted: 0, elapsed: 0 });

    if (sesContent) {
      console.log('[Routing] Loading SES routes...');
      engine.load_routes(sesContent);
      snapshot = engine.get_snapshot();
      dirty = true;
      statusText.textContent = `Routing complete (${elapsed}s)`;
    } else {
      statusText.textContent = `Routing complete, no routes (${elapsed}s)`;
    }

    // Show completion status briefly, then normal
    setTimeout(() => {
      statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
    }, 3000);
  }

  /**
   * Handle routing error from WebSocket
   */
  function handleRouteError(error: string): void {
    isRouting = false;
    updateRoutingUI({ isRouting: false, pass: 0, routed: 0, unrouted: 0, elapsed: 0 });
    statusText.textContent = `Routing error: ${error}`;
    console.error('[Routing] Error:', error);

    setTimeout(() => {
      statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
    }, 5000);
  }

  /**
   * Handle routing progress from WebSocket
   */
  function handleRouteProgress(output: string): void {
    // Parse progress output from CLI (format: "Pass X: Y routed, Z unrouted (Xs)")
    const match = output.match(/Pass (\d+): (\d+) routed, (\d+) unrouted/);
    if (match) {
      const elapsed = Math.round((Date.now() - routingStartTime) / 1000);
      updateRoutingUI({
        isRouting: true,
        pass: parseInt(match[1], 10),
        routed: parseInt(match[2], 10),
        unrouted: parseInt(match[3], 10),
        elapsed,
      });
    }
  }

  /**
   * Cancel the current routing operation
   */
  function cancelRouting(): void {
    if (isRouting) {
      console.log('[Routing] Cancelling routing...');
      // Note: Server-side cancellation not implemented yet
      // For now, just update UI
      isRouting = false;
      updateRoutingUI({ isRouting: false, pass: 0, routed: 0, unrouted: 0, elapsed: 0 });
      statusText.textContent = 'Routing cancelled';
    }
  }

  // Route button click handler
  routeBtn.addEventListener('click', () => {
    triggerRouting();
  });

  // Cancel button click handler
  cancelRouteBtn.addEventListener('click', () => {
    cancelRouting();
  });

  /**
   * Handle saving the current file (web only).
   * Uses File System Access API with handle for save-in-place.
   */
  async function handleSaveFile(): Promise<void> {
    // Use editor content if editor is active, otherwise use lastLoadedSource
    const contentToSave = (editorReady && editorInstance) ? editorInstance.getValue() : lastLoadedSource;

    if (!contentToSave) {
      console.log('[Save] No content to save');
      statusText.textContent = 'No design loaded';
      setTimeout(() => {
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }, 2000);
      return;
    }

    try {
      const defaultName = currentFilePath || 'design.cypcb';
      const newHandle = await saveFile(contentToSave, currentFileHandle, defaultName);

      // Update handle if we got a new one (from save-as)
      if (newHandle) {
        currentFileHandle = newHandle;
      }

      // Show saved status briefly
      statusText.textContent = 'Saved';
      setTimeout(() => {
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }, 1500);

    } catch (err) {
      console.error('[Save] Error saving file:', err);
      statusText.textContent = `Error saving file: ${err}`;
      setTimeout(() => {
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }, 3000);
    }
  }

  /**
   * Handle sharing the current view state via URL
   */
  function handleShareView(): void {
    // Build view state from current viewport and layers
    const activeLayers: string[] = [];
    if (topLayerCb.checked) activeLayers.push('top');
    if (bottomLayerCb.checked) activeLayers.push('bottom');
    if (ratsnestCb.checked) activeLayers.push('ratsnest');

    const viewState = {
      layers: activeLayers,
      zoom: viewport.scale,
      panX: viewport.centerX,
      panY: viewport.centerY,
    };

    // Generate share URL
    const queryString = encodeViewState(viewState);
    const shareUrl = window.location.origin + window.location.pathname + queryString;

    // Copy to clipboard
    navigator.clipboard.writeText(shareUrl).then(() => {
      statusText.textContent = 'Share URL copied!';
      setTimeout(() => {
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }, 2000);
    }).catch((err) => {
      console.error('[Share] Failed to copy to clipboard:', err);
      statusText.textContent = 'Failed to copy share URL';
      setTimeout(() => {
        statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
      }, 2000);
    });
  }

  // Share button (web only)
  if (!isDesktop()) {
    shareBtn.classList.remove('hidden');
    shareBtn.addEventListener('click', handleShareView);
  }

  // Keyboard shortcuts
  document.addEventListener('keydown', async (e) => {
    // Escape: cancel manual routing first, then autorouting
    if (e.key === 'Escape') {
      if (routingState.mode === 'routing') {
        routingState = cancelRoute(routingState);
        interactionState.routing = routingState;
        interactionState.onRoutingChange(routingState);
        dirty = true;
        e.preventDefault();
        return;
      }
      if (isRouting) {
        cancelRouting();
        return;
      }
    }

    // Delete: remove selected trace
    if ((e.key === 'Delete' || e.key === 'Backspace') && routingState.mode === 'idle') {
      if (selectedTraceId != null) {
        const removed = engine.remove_trace(selectedTraceId);
        if (removed) {
          console.log(`[Route] Deleted trace id=${selectedTraceId}`);
          engine.run_drc_incremental();
          snapshot = engine.get_snapshot();
          interactionState.snapshot = snapshot;
          selectedTraceId = null;
          interactionState.selectedTraceId = null;
          interactionState.onTraceSelect(null, 0, 0);
          labelPosition = null;
          statusText.textContent = 'Trace deleted';
          setTimeout(() => {
            statusText.textContent = usingWasm ? 'Ready (WASM)' : 'Ready (Mock)';
          }, 1500);
        }
        dirty = true;
        e.preventDefault();
        return;
      }
    }
    // F: flip layer during routing, or fit board to view when idle
    if (e.key === 'f' && !e.ctrlKey && !e.metaKey && !e.altKey) {
      if (routingState.mode === 'routing') {
        routingState = flipLayer(routingState);
        interactionState.routing = routingState;
        interactionState.onRoutingChange(routingState);
        statusText.textContent = `Layer: ${routingState.currentLayer}`;
        dirty = true;
        e.preventDefault();
      } else {
        fitBtn.click();
      }
    }
    // Ctrl+E to toggle editor
    if ((e.ctrlKey || e.metaKey) && e.key === 'e') {
      e.preventDefault();
      editorToggleBtn.click();
    }
    // Ctrl+Shift+T to toggle theme
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'T') {
      e.preventDefault();
      themeToggle.click();
    }
    // Ctrl+S to save (web only - desktop uses native menu)
    if ((e.ctrlKey || e.metaKey) && e.key === 's' && !isDesktop()) {
      e.preventDefault();
      await handleSaveFile();
    }
    // Ctrl+Shift+S to share (web only)
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'S' && !isDesktop()) {
      e.preventDefault();
      handleShareView();
    }
    // '3' key toggles 3D view (skip if typing in editor/input)
    if (e.key === '3' && !e.ctrlKey && !e.metaKey && !e.altKey) {
      const tag = (e.target as HTMLElement)?.tagName;
      const isEditorFocused = tag === 'INPUT' || tag === 'TEXTAREA' ||
        (e.target as HTMLElement)?.closest('.monaco-editor') != null;
      if (!isEditorFocused) {
        e.preventDefault();
        view3dBtn.click();
      }
    }
  });

  // Connect WebSocket for hot reload and routing
  try {
    wsConnection = connectWebSocket({
      onReload: (content, file) => {
        // Skip WebSocket init if URL has state (shared link)
        if (hasUrlState && !currentFilePath) {
          console.log('[WS] Skipping init - URL state present');
          hasUrlState = false; // Only skip first init
          return;
        }

        // Track current file for routing
        currentFilePath = file;
        reload(content, file);

        // Auto-route if enabled
        if (autoRouteCb.checked && !isRouting) {
          // Small delay to let reload complete
          setTimeout(() => {
            triggerRouting();
          }, 500);
        }
      },
      onRouteStart: () => {
        console.log('[Routing] Server started routing...');
      },
      onRouteProgress: (output) => {
        handleRouteProgress(output);
      },
      onRouteComplete: (sesContent, routesContent) => {
        handleRouteComplete(sesContent, routesContent);
      },
      onRouteError: (error) => {
        handleRouteError(error);
      },
    });
  } catch (err) {
    console.log('[WS] WebSocket not available');
  }

  // Initialize desktop integration if running in Tauri
  if (isDesktop()) {
    await initDesktop();

    // Desktop event listeners - handle custom events from desktop.ts
    window.addEventListener('desktop:open-file', (event: Event) => {
      const customEvent = event as CustomEvent<{ path: string; content: string }>;
      const { path, content } = customEvent.detail;

      console.log('[Desktop] Opening file:', path);

      // Load the content into the engine
      const errors = engine.load_source(content);
      if (errors) {
        console.warn('[Desktop] Parse warnings:', errors);
      }

      // Track loaded source for save operations
      lastLoadedSource = content;

      // Update snapshot
      snapshot = engine.get_snapshot();

      // Update editor content if initialized
      if (editorReady && editorInstance) {
        suppressSync = true;
        editorInstance.setValue(content);
        suppressSync = false;

        // Update inline diagnostics
        const monaco = getMonacoModule();
        if (monaco) {
          updateDiagnostics(monaco, editorInstance, errors, snapshot.violations || []);
        }
      }

      // Update error badge
      if (snapshot.violations) {
        updateErrorBadge(snapshot.violations);
      }

      // Fit board in viewport if it exists
      if (snapshot.board) {
        viewport = fitBoard(viewport, snapshot.board.width_nm, snapshot.board.height_nm);
        interactionState.viewport = viewport;
      }

      // Update current file path for routing
      currentFilePath = path;

      // Update status with filename
      const filename = path.split(/[/\\]/).pop() || path;
      const errorCount = errors ? errors.split('\n').filter(Boolean).length : 0;
      statusText.textContent = errorCount > 0
        ? `Loaded ${filename} (${errorCount} warnings)`
        : `Loaded ${filename}`;

      dirty = true;
    });

    window.addEventListener('desktop:content-request', () => {
      console.log('[Desktop] Content requested for save');

      // Use editor content if editor is active, otherwise use lastLoadedSource
      const contentToSave = (editorReady && editorInstance) ? editorInstance.getValue() : lastLoadedSource;

      // Respond with current source content
      const event = new CustomEvent('desktop:content-response', {
        detail: { content: contentToSave },
      });
      window.dispatchEvent(event);
    });

    window.addEventListener('desktop:viewport', (event: Event) => {
      const customEvent = event as CustomEvent<{ action: 'zoom-in' | 'zoom-out' | 'fit' }>;
      const { action } = customEvent.detail;

      console.log('[Desktop] Viewport action:', action);

      switch (action) {
        case 'zoom-in':
          viewport = {
            ...viewport,
            scale: viewport.scale * 1.5,
          };
          interactionState.viewport = viewport;
          dirty = true;
          break;

        case 'zoom-out':
          viewport = {
            ...viewport,
            scale: viewport.scale * 0.6667,
          };
          interactionState.viewport = viewport;
          dirty = true;
          break;

        case 'fit':
          if (snapshot?.board) {
            viewport = fitBoard(viewport, snapshot.board.width_nm, snapshot.board.height_nm);
            interactionState.viewport = viewport;
            dirty = true;
          }
          break;
      }
    });

    window.addEventListener('desktop:toggle-theme', () => {
      console.log('[Desktop] Toggle theme');

      const current = themeManager.getTheme();
      // Cycle: light → dark → auto → light
      const next = current === 'light' ? 'dark' : current === 'dark' ? 'auto' : 'light';
      themeManager.setTheme(next);
      updateThemeIcon();
    });

    window.addEventListener('desktop:new-file', () => {
      console.log('[Desktop] New file');

      // Clear the design
      engine.load_source('');
      snapshot = engine.get_snapshot();

      // Clear editor content if initialized
      if (editorReady && editorInstance) {
        suppressSync = true;
        editorInstance.setValue('');
        suppressSync = false;

        // Clear inline diagnostics
        const monaco = getMonacoModule();
        if (monaco) {
          updateDiagnostics(monaco, editorInstance, null, []);
        }
      }

      // Clear file state
      currentFilePath = null;
      lastLoadedSource = null;

      // Update status
      statusText.textContent = usingWasm ? 'Ready (WASM) - Open a file' : 'Ready (Mock) - Open a file';

      dirty = true;
    });
  }
}

// Start the application
init().catch((error) => {
  console.error('Failed to initialize viewer:', error);
  const statusText = document.getElementById('status-text');
  if (statusText) {
    statusText.textContent = 'Error: ' + (error instanceof Error ? error.message : String(error));
  }
});

/**
 * Canvas 2D rendering functions for PCB visualization
 * Draws board outline, components, pads, and grid
 */

import type { BoardSnapshot, ComponentInfo, PadInfo, ViolationInfo, TraceInfo, ViaInfo, RatsnestInfo } from './types';
import type { Viewport } from './viewport';
import type { RoutingState } from './routing';
import { worldToScreen, screenToWorld } from './viewport';
import { LAYER_COLORS, getPadColor, getTraceColor, getThemeColors, netColor, brightenColor, colorWithAlpha, type LayerVisibility } from './layers';

export interface RenderState {
  snapshot: BoardSnapshot | null;
  viewport: Viewport;
  layers: LayerVisibility;
  selectedRefdes: string | null;
  showViolations: boolean;
  showRatsnest: boolean;
  colorByNet: boolean;
  selectedTraceId: number | null;
  hoveredTraceId: number | null;
  /** Screen position for the net label tooltip (set by interaction layer) */
  labelPosition: { x: number; y: number } | null;
  /** Active routing state (null when not routing) */
  routing: RoutingState | null;
}

/**
 * Main render function - draws entire board state
 */
export function render(ctx: CanvasRenderingContext2D, state: RenderState): void {
  const { snapshot, viewport, layers, selectedRefdes, showViolations, showRatsnest } = state;

  // Get theme-dependent colors
  const themeColors = getThemeColors();

  // Clear canvas with background color
  ctx.fillStyle = themeColors.background;
  ctx.fillRect(0, 0, viewport.width, viewport.height);

  if (!snapshot || !snapshot.board) {
    drawEmptyState(ctx, viewport, themeColors);
    return;
  }

  // Draw grid (behind everything)
  drawGrid(ctx, viewport, themeColors);

  // Draw board outline
  drawBoardOutline(ctx, viewport, snapshot.board.width_nm, snapshot.board.height_nm, themeColors);

  // Draw traces by layer (bottom first, then top)
  if (snapshot.traces) {
    const { colorByNet, selectedTraceId, hoveredTraceId } = state;
    // Bottom traces first
    for (const trace of snapshot.traces) {
      if (trace.layer === 'Bottom' && layers.bottomCopper) {
        drawTrace(ctx, viewport, trace, layers, colorByNet, selectedTraceId, hoveredTraceId);
      }
    }
    // Top traces on top
    for (const trace of snapshot.traces) {
      if (trace.layer === 'Top' && layers.topCopper) {
        drawTrace(ctx, viewport, trace, layers, colorByNet, selectedTraceId, hoveredTraceId);
      }
    }
    // Inner layers
    for (const trace of snapshot.traces) {
      if (trace.layer !== 'Top' && trace.layer !== 'Bottom') {
        drawTrace(ctx, viewport, trace, layers, colorByNet, selectedTraceId, hoveredTraceId);
      }
    }
  }

  // Draw components (pads and labels)
  for (const comp of snapshot.components) {
    const isSelected = comp.refdes === selectedRefdes;
    drawComponent(ctx, viewport, comp, layers, isSelected, themeColors);
  }

  // Draw vias on top of traces but below ratsnest
  if (snapshot.vias) {
    for (const via of snapshot.vias) {
      // Vias visible if any copper layer is visible
      if (layers.topCopper || layers.bottomCopper) {
        drawVia(ctx, viewport, via, themeColors);
      }
    }
  }

  // Draw ratsnest on top of everything (except violations)
  if (showRatsnest && snapshot.ratsnest) {
    for (const line of snapshot.ratsnest) {
      drawRatsnest(ctx, viewport, line);
    }
  }

  // Draw violations on top of everything
  if (showViolations && snapshot.violations) {
    for (const violation of snapshot.violations) {
      drawViolation(ctx, viewport, violation);
    }
  }

  // Draw routing preview (dashed trace + DRC markers)
  if (state.routing && state.routing.mode === 'routing') {
    drawRoutingPreview(ctx, viewport, state.routing);
  }

  // Draw net label for selected trace
  if (state.selectedTraceId != null && state.labelPosition && snapshot.traces) {
    const selectedTrace = snapshot.traces.find(t => t.id === state.selectedTraceId);
    if (selectedTrace) {
      drawNetLabel(ctx, state.labelPosition.x, state.labelPosition.y, selectedTrace);
    }
  }
}

/**
 * Draw placeholder when no board is loaded
 */
function drawEmptyState(ctx: CanvasRenderingContext2D, viewport: Viewport, themeColors: ReturnType<typeof getThemeColors>): void {
  ctx.fillStyle = themeColors.empty_text;
  ctx.font = '16px system-ui';
  ctx.textAlign = 'center';
  ctx.fillText('No board loaded', viewport.width / 2, viewport.height / 2);
}

/**
 * Draw grid lines
 * Adapts grid density based on zoom level for readability
 */
function drawGrid(ctx: CanvasRenderingContext2D, vp: Viewport, themeColors: ReturnType<typeof getThemeColors>): void {
  // 1mm grid spacing (1,000,000 nm)
  const gridSpacing = 1_000_000;

  // Only draw if grid lines would be at least 10px apart
  const screenSpacing = gridSpacing * vp.scale;
  if (screenSpacing < 10) return;

  ctx.strokeStyle = themeColors.grid;
  ctx.lineWidth = 1;

  // Calculate visible world bounds
  const [minX, maxY] = screenToWorld(vp, 0, 0);
  const [maxX, minY] = screenToWorld(vp, vp.width, vp.height);

  // Round to grid boundaries
  const startX = Math.floor(minX / gridSpacing) * gridSpacing;
  const startY = Math.floor(minY / gridSpacing) * gridSpacing;

  ctx.beginPath();

  // Vertical lines
  for (let x = startX; x <= maxX; x += gridSpacing) {
    const [sx] = worldToScreen(vp, x, 0);
    ctx.moveTo(sx, 0);
    ctx.lineTo(sx, vp.height);
  }

  // Horizontal lines
  for (let y = startY; y <= maxY; y += gridSpacing) {
    const [, sy] = worldToScreen(vp, 0, y);
    ctx.moveTo(0, sy);
    ctx.lineTo(vp.width, sy);
  }

  ctx.stroke();
}

/**
 * Draw board outline as yellow rectangle
 */
function drawBoardOutline(ctx: CanvasRenderingContext2D, vp: Viewport, width: number, height: number, themeColors: ReturnType<typeof getThemeColors>): void {
  const [x0, y0] = worldToScreen(vp, 0, 0);
  const [x1, y1] = worldToScreen(vp, width, height);

  ctx.strokeStyle = themeColors.board_outline;
  ctx.lineWidth = 2;
  // Note: y0/y1 are flipped due to Y-down screen coords
  ctx.strokeRect(x0, y1, x1 - x0, y0 - y1);
}

/**
 * Draw a violation marker (red circle/ring) at the violation location
 * KiCad-style marker with outer ring and inner highlight
 */
function drawViolation(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  violation: ViolationInfo
): void {
  const [sx, sy] = worldToScreen(vp, violation.x_nm, violation.y_nm);

  // Ring style marker (KiCad-like)
  const radius = 15; // Fixed screen pixels
  const innerRadius = 10;

  // Outer ring
  ctx.beginPath();
  ctx.arc(sx, sy, radius, 0, Math.PI * 2);
  ctx.strokeStyle = LAYER_COLORS.violation_ring;
  ctx.lineWidth = 3;
  ctx.stroke();

  // Inner highlight (semi-transparent fill)
  ctx.beginPath();
  ctx.arc(sx, sy, innerRadius, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255, 0, 0, 0.3)';
  ctx.fill();
}

/**
 * Build the polyline path for a trace (reused by main stroke, glow, and locked overlay)
 */
function tracePolyline(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  trace: TraceInfo
): void {
  ctx.beginPath();
  const firstSeg = trace.segments[0];
  const [startX, startY] = worldToScreen(vp, firstSeg.start_x, firstSeg.start_y);
  ctx.moveTo(startX, startY);
  for (const seg of trace.segments) {
    const [endX, endY] = worldToScreen(vp, seg.end_x, seg.end_y);
    ctx.lineTo(endX, endY);
  }
}

/**
 * Draw a copper trace
 * Renders as a thick polyline with rounded ends.
 * Supports per-net coloring, selection highlight (glow + wider stroke),
 * and hover highlight (lighter overlay).
 */
function drawTrace(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  trace: TraceInfo,
  layers: LayerVisibility,
  colorByNet: boolean,
  selectedTraceId: number | null,
  hoveredTraceId: number | null,
): void {
  if (trace.segments.length === 0) return;

  // Determine base color — net color or layer color
  let color: string | null;
  if (colorByNet && trace.net_name) {
    // Still check layer visibility
    const layerVisible = getTraceColor(trace.layer, layers) !== null;
    if (!layerVisible) return;
    color = netColor(trace.net_name);
  } else {
    color = getTraceColor(trace.layer, layers);
  }
  if (!color) return;

  const isSelected = trace.id === selectedTraceId;
  const isHovered = trace.id === hoveredTraceId && !isSelected;

  // Calculate line width in screen pixels
  const baseLineWidth = trace.width * vp.scale;
  if (baseLineWidth < 0.5) return;

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Selection glow — wider semi-transparent stroke behind
  if (isSelected) {
    const glowColor = colorWithAlpha(brightenColor(color, 25), 0.35);
    ctx.strokeStyle = glowColor;
    ctx.lineWidth = baseLineWidth * 2.5;
    tracePolyline(ctx, vp, trace);
    ctx.stroke();
  }

  // Main trace stroke
  const drawColor = isSelected ? brightenColor(color, 20) : color;
  const lineWidth = isSelected ? baseLineWidth * 1.5 : baseLineWidth;

  ctx.strokeStyle = drawColor;
  ctx.lineWidth = lineWidth;
  tracePolyline(ctx, vp, trace);
  ctx.stroke();

  // Hover overlay — lighter semi-transparent stroke on top
  if (isHovered) {
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.25)';
    ctx.lineWidth = baseLineWidth;
    tracePolyline(ctx, vp, trace);
    ctx.stroke();
  }

  // Locked indicator (subtle dashed overlay)
  if (trace.locked && baseLineWidth > 2) {
    ctx.save();
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
    ctx.lineWidth = Math.max(1, baseLineWidth * 0.3);
    tracePolyline(ctx, vp, trace);
    ctx.stroke();
    ctx.restore();
  }
}

/**
 * Draw a net name + width label near the cursor for the selected trace.
 * Semi-transparent badge style.
 */
function drawNetLabel(
  ctx: CanvasRenderingContext2D,
  screenX: number,
  screenY: number,
  trace: TraceInfo
): void {
  const widthMm = (trace.width / 1_000_000).toFixed(2);
  const label = `${trace.net_name} — ${widthMm}mm`;

  ctx.font = '12px system-ui, sans-serif';
  const metrics = ctx.measureText(label);
  const padX = 8;
  const boxW = metrics.width + padX * 2;
  const boxH = 20;
  const offsetX = 15;
  const offsetY = -25;

  const x = screenX + offsetX;
  const y = screenY + offsetY;

  // Background
  ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
  ctx.beginPath();
  ctx.roundRect(x, y, boxW, boxH, 4);
  ctx.fill();

  // Text
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, x + padX, y + boxH / 2);
}

/**
 * Draw a via (plated through-hole connecting layers)
 * Renders as a filled circle with a drill hole
 */
function drawVia(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  via: ViaInfo,
  themeColors: ReturnType<typeof getThemeColors>
): void {
  const [sx, sy] = worldToScreen(vp, via.x, via.y);
  const outerRadius = (via.outer_diameter * vp.scale) / 2;
  const drillRadius = (via.drill * vp.scale) / 2;

  // Don't render if too small to see
  if (outerRadius < 1) return;

  // Draw outer copper ring (use via color - blend of top/bottom)
  ctx.beginPath();
  ctx.arc(sx, sy, outerRadius, 0, Math.PI * 2);
  ctx.fillStyle = LAYER_COLORS.via;
  ctx.fill();

  // Draw drill hole
  if (drillRadius > 0.5) {
    ctx.beginPath();
    ctx.arc(sx, sy, drillRadius, 0, Math.PI * 2);
    ctx.fillStyle = themeColors.background;
    ctx.fill();
  }
}

/**
 * Draw a ratsnest line (unrouted connection indicator)
 * Thin dashed line in high-visibility color
 */
function drawRatsnest(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  line: RatsnestInfo
): void {
  const [startX, startY] = worldToScreen(vp, line.start_x, line.start_y);
  const [endX, endY] = worldToScreen(vp, line.end_x, line.end_y);

  ctx.save();
  ctx.strokeStyle = LAYER_COLORS.ratsnest;
  ctx.lineWidth = 1; // Always 1px regardless of zoom
  ctx.setLineDash([5, 3]); // Dashed pattern

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();

  ctx.restore();
}

/**
 * Draw a component (its pads and label)
 */
function drawComponent(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  comp: ComponentInfo,
  layers: LayerVisibility,
  isSelected: boolean,
  themeColors: ReturnType<typeof getThemeColors>
): void {
  // Draw pads
  for (const pad of comp.pads) {
    drawPad(ctx, vp, comp.x_nm, comp.y_nm, comp.rotation_mdeg, pad, layers, isSelected, themeColors);
  }

  // Draw refdes label if zoomed in enough
  if (vp.scale > 0.00002) {
    const [sx, sy] = worldToScreen(vp, comp.x_nm, comp.y_nm);
    ctx.fillStyle = isSelected ? '#FF6600' : themeColors.label;
    ctx.font = '10px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText(comp.refdes, sx, sy - 5);
  }
}

/**
 * Draw a single pad with rotation and layer-appropriate color
 */
function drawPad(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  compX: number,
  compY: number,
  rotationMdeg: number,
  pad: PadInfo,
  layers: LayerVisibility,
  isSelected: boolean,
  themeColors: ReturnType<typeof getThemeColors>
): void {
  const color = getPadColor(pad.layer_mask, layers);
  if (!color) return; // Layer not visible

  // Calculate pad position in world coords
  // Apply component rotation to pad position
  const radians = (rotationMdeg / 1000) * (Math.PI / 180);
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);

  const rotatedX = pad.x_nm * cos - pad.y_nm * sin;
  const rotatedY = pad.x_nm * sin + pad.y_nm * cos;

  const worldX = compX + rotatedX;
  const worldY = compY + rotatedY;

  const [screenX, screenY] = worldToScreen(vp, worldX, worldY);
  const width = pad.width_nm * vp.scale;
  const height = pad.height_nm * vp.scale;

  // Skip if pad too small to see
  if (width < 0.5 && height < 0.5) return;

  ctx.save();
  ctx.translate(screenX, screenY);
  ctx.rotate(-radians); // Negate for screen Y-down

  // Fill color (orange when selected)
  ctx.fillStyle = isSelected ? '#FF6600' : color;

  switch (pad.shape) {
    case 'circle':
      ctx.beginPath();
      ctx.arc(0, 0, width / 2, 0, Math.PI * 2);
      ctx.fill();
      break;

    case 'rect':
      ctx.fillRect(-width / 2, -height / 2, width, height);
      break;

    case 'roundrect':
      drawRoundRect(ctx, -width / 2, -height / 2, width, height, Math.min(width, height) * 0.25);
      ctx.fill();
      break;

    case 'oblong':
      drawOblong(ctx, -width / 2, -height / 2, width, height);
      ctx.fill();
      break;

    default:
      // Fallback to rect for unknown shapes
      ctx.fillRect(-width / 2, -height / 2, width, height);
  }

  // Draw drill hole for through-hole pads
  if (pad.drill_nm) {
    const drillRadius = pad.drill_nm * vp.scale / 2;
    if (drillRadius > 0.5) {
      ctx.fillStyle = themeColors.background;
      ctx.beginPath();
      ctx.arc(0, 0, drillRadius, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.restore();
}

/**
 * Draw a rounded rectangle path
 */
function drawRoundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number): void {
  // Clamp radius to avoid artifacts
  r = Math.min(r, w / 2, h / 2);

  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

/**
 * Draw an oblong (pill/stadium) shape path
 */
function drawOblong(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number): void {
  // Oblong is like a pill shape (fully rounded ends)
  const r = Math.min(w, h) / 2;
  drawRoundRect(ctx, x, y, w, h, r);
}

/**
 * Draw the routing preview — committed segments (solid) + preview segment (dashed).
 * Also draws DRC violation markers from the live preview check.
 */
function drawRoutingPreview(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  routing: RoutingState,
): void {
  const color = routing.netName ? netColor(routing.netName) : '#00FF00';
  const lineWidth = routing.traceWidth * vp.scale;
  const drawWidth = Math.max(lineWidth, 2); // minimum 2px visibility

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Draw committed segments (solid but semi-transparent)
  if (routing.committedSegments.length > 0) {
    ctx.strokeStyle = colorWithAlpha(color, 0.7);
    ctx.lineWidth = drawWidth;
    ctx.beginPath();
    const first = routing.committedSegments[0];
    const [sx, sy] = worldToScreen(vp, first.start_x, first.start_y);
    ctx.moveTo(sx, sy);
    for (const seg of routing.committedSegments) {
      const [ex, ey] = worldToScreen(vp, seg.end_x, seg.end_y);
      ctx.lineTo(ex, ey);
    }
    ctx.stroke();
  }

  // Draw preview segment (dashed)
  if (routing.previewSegment) {
    const seg = routing.previewSegment;
    const [sx, sy] = worldToScreen(vp, seg.start_x, seg.start_y);
    const [ex, ey] = worldToScreen(vp, seg.end_x, seg.end_y);

    ctx.save();
    ctx.setLineDash([8, 4]);
    ctx.strokeStyle = colorWithAlpha(color, 0.8);
    ctx.lineWidth = drawWidth;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(ex, ey);
    ctx.stroke();
    ctx.restore();

    // Draw endpoint marker (small circle at cursor)
    ctx.beginPath();
    ctx.arc(ex, ey, Math.max(4, drawWidth * 0.6), 0, Math.PI * 2);
    ctx.fillStyle = colorWithAlpha(color, 0.5);
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }

  // Draw anchor point marker
  const [ax, ay] = worldToScreen(vp, routing.anchorPoint.x, routing.anchorPoint.y);
  ctx.beginPath();
  ctx.arc(ax, ay, 5, 0, Math.PI * 2);
  ctx.fillStyle = '#FFFFFF';
  ctx.fill();
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.stroke();

  // Draw DRC violations from preview
  for (const v of routing.drcViolations) {
    const [vx, vy] = worldToScreen(vp, v.x_nm, v.y_nm);
    // Pulsing red ring
    ctx.beginPath();
    ctx.arc(vx, vy, 12, 0, Math.PI * 2);
    ctx.strokeStyle = '#FF0000';
    ctx.lineWidth = 2.5;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(vx, vy, 8, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 0, 0, 0.25)';
    ctx.fill();
  }

  // Draw snap angle indicator text near cursor
  if (routing.previewSegment) {
    const seg = routing.previewSegment;
    const [ex, ey] = worldToScreen(vp, seg.end_x, seg.end_y);
    ctx.font = '11px system-ui, sans-serif';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
    ctx.textAlign = 'left';
    ctx.fillText(`${routing.snapAngle}°`, ex + 12, ey - 8);

    // Show net name + layer indicator
    let label = routing.currentLayer;
    if (routing.netName) label = `${routing.netName} [${routing.currentLayer}]`;
    ctx.fillText(label, ex + 12, ey + 6);
  }
}

/**
 * Create an initial render state
 */
export function createRenderState(viewport: Viewport, layers: LayerVisibility): RenderState {
  return {
    snapshot: null,
    viewport,
    layers,
    selectedRefdes: null,
    showViolations: true,
    showRatsnest: true,
    colorByNet: true,
    selectedTraceId: null,
    hoveredTraceId: null,
    labelPosition: null,
    routing: null,
  };
}

/**
 * Update render state with new snapshot
 */
export function updateSnapshot(state: RenderState, snapshot: BoardSnapshot): RenderState {
  return {
    ...state,
    snapshot,
  };
}

/**
 * Update render state with new viewport
 */
export function updateViewport(state: RenderState, viewport: Viewport): RenderState {
  return {
    ...state,
    viewport,
  };
}

/**
 * Update render state with new layer visibility
 */
export function updateLayers(state: RenderState, layers: LayerVisibility): RenderState {
  return {
    ...state,
    layers,
  };
}

/**
 * Update selection
 */
export function updateSelection(state: RenderState, refdes: string | null): RenderState {
  return {
    ...state,
    selectedRefdes: refdes,
  };
}

/**
 * Mouse interaction handlers for PCB viewer
 * Provides zoom, pan, and selection behaviors
 */

import type { Viewport } from './viewport';
import type { BoardSnapshot } from './types';
import type { PcbEngine } from './wasm';
import type { RoutingState } from './routing';
import { zoomAtPoint, pan, screenToWorld } from './viewport';
import { hitTestTrace } from './hit-test';
import {
  createRoutingState,
  hitTestPad,
  startRoute,
  updatePreview,
  addWaypoint,
  completeRoute,
  setDrcViolations,
  createDrcPreviewChecker,
} from './routing';

export interface InteractionState {
  viewport: Viewport;
  isPanning: boolean;
  lastX: number;
  lastY: number;
  dirty: boolean;
  onSelect: (x_nm: number, y_nm: number) => void;
  onViewportChange: (vp: Viewport) => void;
  /** Current board snapshot for hit-testing */
  snapshot: BoardSnapshot | null;
  /** Currently selected trace entity ID */
  selectedTraceId: number | null;
  /** Currently hovered trace entity ID */
  hoveredTraceId: number | null;
  /** Callback when trace selection changes */
  onTraceSelect: (traceId: number | null, screenX: number, screenY: number) => void;
  /** Callback when hover trace changes */
  onTraceHover: (traceId: number | null) => void;
  /** Routing state machine */
  routing: RoutingState;
  /** PCB engine for trace mutations during routing */
  engine: PcbEngine | null;
  /** Callback when routing state changes (for re-render) */
  onRoutingChange: (routing: RoutingState) => void;
}

/**
 * Set up all interaction handlers for the canvas
 * - Scroll wheel: zoom centered on cursor (also pinch-to-zoom on touchpad)
 * - Two-finger touchpad/touchscreen drag: pan
 * - Middle-click + drag: pan
 * - Ctrl + left-click + drag: pan (alternative for laptops)
 * - Left-click: select component at point
 * - Right-click: reserved (context menu prevented)
 */
export function setupInteraction(
  canvas: HTMLCanvasElement,
  state: InteractionState
): void {
  // Pointer cache for multi-touch pan detection
  const pointerCache: Array<{ pointerId: number; clientX: number; clientY: number }> = [];

  // Wheel zoom (zoom to cursor position)
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Zoom in on scroll up, out on scroll down
    const factor = e.deltaY < 0 ? 1.15 : 0.87;
    state.viewport = zoomAtPoint(state.viewport, x, y, factor);
    state.dirty = true;
    state.onViewportChange(state.viewport);
  }, { passive: false });

  // Pointer Events for two-finger touchpad/touchscreen pan
  canvas.addEventListener('pointerdown', (e) => {
    pointerCache.push({
      pointerId: e.pointerId,
      clientX: e.clientX,
      clientY: e.clientY,
    });
  });

  canvas.addEventListener('pointermove', (e) => {
    // Find this pointer in cache
    const index = pointerCache.findIndex(p => p.pointerId === e.pointerId);
    if (index === -1) return;

    // If exactly 2 pointers, perform two-finger pan
    if (pointerCache.length === 2) {
      const cached = pointerCache[index];
      const dx = e.clientX - cached.clientX;
      const dy = e.clientY - cached.clientY;

      // Half delta since both fingers contribute to pan
      state.viewport = pan(state.viewport, dx / 2, dy / 2);
      state.dirty = true;
      state.onViewportChange(state.viewport);
    }

    // Update cached position
    pointerCache[index].clientX = e.clientX;
    pointerCache[index].clientY = e.clientY;
  });

  // Shared cleanup function for pointer removal
  const removePointer = (e: PointerEvent) => {
    const index = pointerCache.findIndex(p => p.pointerId === e.pointerId);
    if (index !== -1) {
      pointerCache.splice(index, 1);
    }
  };

  canvas.addEventListener('pointerup', removePointer);
  canvas.addEventListener('pointercancel', removePointer);
  canvas.addEventListener('pointerout', removePointer);
  canvas.addEventListener('pointerleave', removePointer);

  // Middle-click pan OR Ctrl+left-click pan (for laptops without middle button)
  canvas.addEventListener('mousedown', (e) => {
    if (e.button === 1 || (e.button === 0 && e.ctrlKey)) {
      state.isPanning = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      e.preventDefault();
      canvas.style.cursor = 'grabbing';
    }
  });

  canvas.addEventListener('mousemove', (e) => {
    if (state.isPanning) {
      const dx = e.clientX - state.lastX;
      const dy = e.clientY - state.lastY;
      state.viewport = pan(state.viewport, dx, dy);
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      state.dirty = true;
      state.onViewportChange(state.viewport);
    }
  });

  canvas.addEventListener('mouseup', () => {
    if (state.isPanning) {
      state.isPanning = false;
      canvas.style.cursor = 'default';
    }
  });

  canvas.addEventListener('mouseleave', () => {
    if (state.isPanning) {
      state.isPanning = false;
      canvas.style.cursor = 'default';
    }
  });

  // --- DRC preview checker (debounced, used during routing) ---
  let drcChecker: ReturnType<typeof createDrcPreviewChecker> | null = null;

  function ensureDrcChecker(): ReturnType<typeof createDrcPreviewChecker> {
    if (!drcChecker && state.engine) {
      drcChecker = createDrcPreviewChecker(state.engine, 100);
      drcChecker.onViolations((violations) => {
        state.routing = setDrcViolations(state.routing, violations);
        state.onRoutingChange(state.routing);
        state.dirty = true;
      });
    }
    return drcChecker!;
  }

  // Pad hit tolerance — generous for easy targeting (1mm in nm, plus pixel tolerance)
  const PAD_HIT_TOLERANCE_NM = 500_000; // 0.5mm extra

  // Left-click selection (but not if Ctrl held - that's pan)
  canvas.addEventListener('click', (e) => {
    if (e.button !== 0 || e.ctrlKey) return; // Left click only, no Ctrl

    const rect = canvas.getBoundingClientRect();
    const screenX = e.clientX - rect.left;
    const screenY = e.clientY - rect.top;
    const [worldX, worldY] = screenToWorld(state.viewport, screenX, screenY);

    // ---- Routing state machine: click handling ----
    if (state.routing.mode === 'routing') {
      // While routing: check if we clicked a pad to complete, or empty space for waypoint
      const padHit = hitTestPad(state.snapshot, worldX, worldY, PAD_HIT_TOLERANCE_NM);

      if (padHit) {
        // Complete the route
        const result = completeRoute(state.routing, padHit);
        if (result && state.engine) {
          // Build flat segment array
          const flat: number[] = [];
          for (const s of result.segments) {
            flat.push(Math.round(s.start_x), Math.round(s.start_y), Math.round(s.end_x), Math.round(s.end_y));
          }
          const traceId = state.engine.add_trace(result.netName, result.layer, result.width, flat);
          if (traceId !== 0xFFFFFFFF) {
            console.log(`[Route] Trace added: id=${traceId} net=${result.netName}`);
            // Run DRC after adding
            state.engine.run_drc_incremental();
          } else {
            console.warn('[Route] Failed to add trace');
          }
        }
        // Reset to idle
        state.routing = createRoutingState();
        if (drcChecker) drcChecker.cancel();
        state.onRoutingChange(state.routing);
        state.dirty = true;
        return;
      }

      // No pad hit — add waypoint
      state.routing = addWaypoint(state.routing);
      state.onRoutingChange(state.routing);
      state.dirty = true;
      return;
    }

    // ---- Idle mode: check pads first (to start routing), then traces, then components ----

    // Hit-test pads to start routing
    const padHit = hitTestPad(state.snapshot, worldX, worldY, PAD_HIT_TOLERANCE_NM);
    if (padHit && padHit.netName) {
      state.routing = startRoute(state.routing, padHit);
      ensureDrcChecker();
      state.onRoutingChange(state.routing);
      state.dirty = true;
      return;
    }

    // Try trace hit-test
    const hit = hitTestTrace(state.snapshot, state.viewport, screenX, screenY);
    if (hit) {
      state.selectedTraceId = hit.trace.id;
      state.onTraceSelect(hit.trace.id, e.clientX, e.clientY);
      console.log('[Trace] Selected:', hit.trace.net_name, 'id:', hit.trace.id, 'seg:', hit.segmentIndex);
      state.dirty = true;
      return;
    }

    // No trace hit — deselect trace and fall through to component selection
    if (state.selectedTraceId !== null) {
      state.selectedTraceId = null;
      state.onTraceSelect(null, 0, 0);
      state.dirty = true;
    }

    state.onSelect(worldX, worldY);
  });

  // Hover tracking for traces + routing preview (rAF-guarded)
  let hoverRafPending = false;
  canvas.addEventListener('mousemove', (e) => {
    if (state.isPanning || hoverRafPending) return;

    hoverRafPending = true;
    requestAnimationFrame(() => {
      hoverRafPending = false;
      const rect = canvas.getBoundingClientRect();
      const screenX = e.clientX - rect.left;
      const screenY = e.clientY - rect.top;
      const [worldX, worldY] = screenToWorld(state.viewport, screenX, screenY);

      // --- Routing preview update ---
      if (state.routing.mode === 'routing') {
        state.routing = updatePreview(state.routing, { x: worldX, y: worldY });
        state.onRoutingChange(state.routing);

        // Schedule debounced DRC check
        const checker = ensureDrcChecker();
        if (checker) checker.check(state.routing);

        state.dirty = true;
        canvas.style.cursor = 'crosshair';
        return;
      }

      // --- Normal hover for traces ---
      const hit = hitTestTrace(state.snapshot, state.viewport, screenX, screenY);
      const newHovered = hit ? hit.trace.id : null;

      if (newHovered !== state.hoveredTraceId) {
        state.hoveredTraceId = newHovered;
        state.onTraceHover(newHovered);
        state.dirty = true;

        // Update cursor
        canvas.style.cursor = newHovered != null ? 'pointer' : 'default';
      }
    });
  });

  canvas.addEventListener('mouseleave', () => {
    if (state.hoveredTraceId !== null) {
      state.hoveredTraceId = null;
      state.onTraceHover(null);
      state.dirty = true;
    }
  });

  // Prevent context menu on right-click (reserve for future)
  canvas.addEventListener('contextmenu', (e) => e.preventDefault());
}

/**
 * Create initial interaction state
 */
export function createInteractionState(
  viewport: Viewport,
  onSelect: (x_nm: number, y_nm: number) => void,
  onViewportChange: (vp: Viewport) => void
): InteractionState {
  return {
    viewport,
    isPanning: false,
    lastX: 0,
    lastY: 0,
    dirty: false,
    onSelect,
    onViewportChange,
    snapshot: null,
    selectedTraceId: null,
    hoveredTraceId: null,
    onTraceSelect: () => {},
    onTraceHover: () => {},
    routing: createRoutingState(),
    engine: null,
    onRoutingChange: () => {},
  };
}

/**
 * Layer colors and visibility definitions
 * KiCad-style colors for familiar PCB visualization
 */

// PCB electrical layer colors (fixed, not theme-dependent)
export const LAYER_COLORS = {
  top_copper: '#C83434',       // Red
  bottom_copper: '#3434C8',    // Blue
  top_silk: '#C8C8C8',         // Light gray
  bottom_silk: '#808080',      // Gray
  drill: '#FFFFFF',            // White (on dark) or black (on light)
  violation: '#FF0000',        // Red for DRC errors
  violation_ring: '#FF0000',   // Ring outline for violation markers
  via: '#808080',              // Gray for vias (between top/bottom)
  ratsnest: '#FFD700',         // Gold/Yellow for unrouted connections
} as const;

/**
 * Get current theme colors by reading CSS custom properties
 * These colors change based on the active theme (light/dark)
 */
export function getThemeColors() {
  const style = getComputedStyle(document.documentElement);
  return {
    background: style.getPropertyValue('--bg-canvas').trim() || '#ffffff',
    grid: style.getPropertyValue('--pcb-grid').trim() || '#e0e0e0',
    board_outline: style.getPropertyValue('--pcb-board-outline').trim() || '#cccc00',
    empty_text: style.getPropertyValue('--pcb-empty-text').trim() || '#666666',
    label: style.getPropertyValue('--pcb-label').trim() || '#333333',
  };
}

// Layer bit masks (match cypcb-world Layer enum)
export const LAYER_MASK = {
  TOP_COPPER: 0x00000001,
  BOTTOM_COPPER: 0x00000002,
  // Inner layers would be 0x00000004, 0x00000008, etc.
} as const;

export interface LayerVisibility {
  topCopper: boolean;
  bottomCopper: boolean;
}

/**
 * Create default layer visibility (all visible)
 */
export function createLayerVisibility(): LayerVisibility {
  return {
    topCopper: true,
    bottomCopper: true,
  };
}

/**
 * Toggle a specific layer's visibility
 */
export function toggleLayer(layers: LayerVisibility, layer: keyof LayerVisibility): LayerVisibility {
  return {
    ...layers,
    [layer]: !layers[layer],
  };
}

/**
 * Get color for a pad based on its layer mask and visibility settings
 * Returns null if the pad should not be drawn (layer hidden)
 */
export function getPadColor(layerMask: number, visibility: LayerVisibility): string | null {
  // Through-hole pads (on both layers)
  if ((layerMask & LAYER_MASK.TOP_COPPER) && (layerMask & LAYER_MASK.BOTTOM_COPPER)) {
    // Show if either layer visible
    if (visibility.topCopper || visibility.bottomCopper) {
      return '#C8C8C8'; // Gray for through-hole
    }
    return null;
  }

  // Top-only SMD
  if (layerMask & LAYER_MASK.TOP_COPPER) {
    return visibility.topCopper ? LAYER_COLORS.top_copper : null;
  }

  // Bottom-only SMD
  if (layerMask & LAYER_MASK.BOTTOM_COPPER) {
    return visibility.bottomCopper ? LAYER_COLORS.bottom_copper : null;
  }

  return null;
}

/**
 * Check if a layer mask is on the top layer
 */
export function isTopLayer(layerMask: number): boolean {
  return (layerMask & LAYER_MASK.TOP_COPPER) !== 0;
}

/**
 * Check if a layer mask is on the bottom layer
 */
export function isBottomLayer(layerMask: number): boolean {
  return (layerMask & LAYER_MASK.BOTTOM_COPPER) !== 0;
}

/**
 * Check if a layer mask is through-hole (both layers)
 */
export function isThroughHole(layerMask: number): boolean {
  return isTopLayer(layerMask) && isBottomLayer(layerMask);
}

// Well-known net name color overrides
const NET_COLOR_OVERRIDES: Record<string, string> = {
  'VCC': 'hsl(0, 80%, 50%)',       // Red
  'VDD': 'hsl(0, 80%, 50%)',       // Red
  '+5V': 'hsl(0, 80%, 50%)',       // Red
  '+3V3': 'hsl(30, 90%, 50%)',     // Orange
  '3V3': 'hsl(30, 90%, 50%)',      // Orange
  '+3.3V': 'hsl(30, 90%, 50%)',    // Orange
  'GND': 'hsl(220, 70%, 35%)',     // Dark blue
  'AGND': 'hsl(220, 70%, 35%)',    // Dark blue
  'DGND': 'hsl(220, 70%, 35%)',    // Dark blue
};

/**
 * Generate a deterministic color for a net name.
 * Hashes the name to a hue (0-360), uses fixed saturation and lightness.
 * Common power/ground nets get recognizable overrides.
 */
export function netColor(netName: string): string {
  // Check overrides first (case-insensitive)
  const upper = netName.toUpperCase();
  if (NET_COLOR_OVERRIDES[upper]) {
    return NET_COLOR_OVERRIDES[upper];
  }

  // Simple string hash → hue
  let hash = 0;
  for (let i = 0; i < netName.length; i++) {
    hash = ((hash << 5) - hash + netName.charCodeAt(i)) | 0;
  }
  // Map to 0-360 hue, avoid red/blue zone used by overrides
  const hue = ((hash % 360) + 360) % 360;
  return `hsl(${hue}, 70%, 50%)`;
}

/**
 * Brighten a color for selection highlight.
 * Works with both HSL strings and hex colors.
 */
export function brightenColor(color: string, amount: number = 15): string {
  const hslMatch = color.match(/hsl\((\d+),\s*(\d+)%,\s*(\d+)%\)/);
  if (hslMatch) {
    const h = parseInt(hslMatch[1]);
    const s = parseInt(hslMatch[2]);
    const l = Math.min(85, parseInt(hslMatch[3]) + amount);
    return `hsl(${h}, ${s}%, ${l}%)`;
  }
  // Hex fallback — lighten by mixing with white
  return color;
}

/**
 * Convert a color to an RGBA string with given alpha.
 * Works with HSL strings.
 */
export function colorWithAlpha(color: string, alpha: number): string {
  const hslMatch = color.match(/hsl\((\d+),\s*(\d+)%,\s*(\d+)%\)/);
  if (hslMatch) {
    return `hsla(${hslMatch[1]}, ${hslMatch[2]}%, ${hslMatch[3]}%, ${alpha})`;
  }
  // Hex fallback — use canvas helper not available here, just return as-is
  return color;
}

/**
 * Get color for a trace based on its layer name and visibility settings
 * Returns null if the layer is not visible
 */
export function getTraceColor(layer: string, visibility: LayerVisibility): string | null {
  switch (layer) {
    case 'Top':
      return visibility.topCopper ? LAYER_COLORS.top_copper : null;
    case 'Bottom':
      return visibility.bottomCopper ? LAYER_COLORS.bottom_copper : null;
    default:
      // Inner layers - show if any copper layer is visible
      if (visibility.topCopper || visibility.bottomCopper) {
        return '#34C834'; // Green for inner layers
      }
      return null;
  }
}

/**
 * WASM module loading utilities
 *
 * This module provides the interface for loading the PcbEngine from WASM.
 * If the WASM module is not available, it falls back to a mock implementation
 * that provides the same interface for development and testing.
 *
 * Architecture note: The WASM build doesn't include tree-sitter (too complex for WASM),
 * so parsing is done in JavaScript. The WASM engine provides:
 * - load_snapshot(): Load a pre-parsed BoardSnapshot
 * - get_snapshot(): Get the current board state
 * - query_point(): Query components at a point
 *
 * This module provides an adapter (WasmPcbEngineAdapter) that adds load_source()
 * by parsing in JavaScript and calling load_snapshot() on the WASM engine.
 */

import type { BoardSnapshot, ComponentInfo, PadInfo, NetInfo, PinRef, BoardInfo, TraceSegmentInfo, ViolationInfo } from './types';

/**
 * Interface for the PCB rendering engine exposed from Rust/WASM
 */
export interface PcbEngine {
  /** Load and parse a .cypcb source file, returns error message if failed */
  load_source(source: string): string;
  /** Load routing results from .ses file content */
  load_routes(sesContent: string): void;
  /** Get the current board state as a snapshot */
  get_snapshot(): BoardSnapshot;
  /** Query what's at a specific point (in nanometers), returns list of entity descriptions */
  query_point(x_nm: number, y_nm: number): string[];

  // -- Trace mutation API (T03) --

  /**
   * Add a trace to the board.
   * @param net_name Net this trace belongs to
   * @param layer "Top" | "Bottom" | "Inner0" etc.
   * @param width_nm Trace width in nanometers
   * @param segments Flat coordinate array [x1,y1,x2,y2, x3,y3,x4,y4, ...] (4 values per segment, in nm)
   * @returns Entity index (u32), or 0xFFFFFFFF on error
   */
  add_trace(net_name: string, layer: string, width_nm: number, segments: number[]): number;

  /**
   * Remove a trace by entity index.
   * @returns true if found and removed
   */
  remove_trace(trace_id: number): boolean;

  /**
   * Find a trace entity at a given point with tolerance.
   * @param x_nm X coordinate in nanometers
   * @param y_nm Y coordinate in nanometers
   * @param tolerance_nm Search radius in nanometers
   * @returns Entity index, or 0xFFFFFFFF if none found
   */
  get_trace_at_point(x_nm: number, y_nm: number, tolerance_nm: number): number;

  /**
   * Run DRC and return the number of violations.
   */
  run_drc_incremental(): number;

  /**
   * Get the number of trace entities.
   */
  trace_count(): number;

  /** Free the engine (for WASM memory management) */
  free?(): void;
}

/**
 * Raw WASM PcbEngine interface (what Rust actually exports)
 */
interface WasmPcbEngine {
  load_snapshot(snapshot: BoardSnapshot): string;
  get_snapshot(): BoardSnapshot;
  query_point(x_nm: bigint, y_nm: bigint): string[];
  add_trace_json(net_name: string, layer_str: string, width_nm: bigint, segments_json: string): number;
  remove_trace(trace_id: number): boolean;
  get_trace_at_point(x_nm: bigint, y_nm: bigint, tolerance_nm: bigint): number;
  run_drc_incremental(): number;
  trace_count(): number;
  get_violations_json(): string;
  free(): void;
}

let wasmModule: any = null;
let engineInstance: PcbEngine | null = null;

// ============================================================================
// Shared parsing utilities (used by both Mock and WASM adapter)
// ============================================================================

/**
 * Parse a unit value to nanometers.
 */
function parseUnit(value: number, unit: string): number {
  switch (unit) {
    case 'mm':
      return Math.round(value * 1_000_000);
    case 'mil':
      return Math.round(value * 25_400);
    case 'inch':
      return Math.round(value * 25_400_000);
    default:
      return Math.round(value * 1_000_000);
  }
}

/**
 * Get standard pad definitions for common footprints.
 */
function getFootprintPads(footprint: string): PadInfo[] {
  // Pad templates must match the Rust footprint library (cypcb-world/src/footprint/).
  // All coordinates are in nanometers, relative to component origin.
  // layer_mask: 1 = TopCopper (SMD), 3 = TopCopper|BottomCopper (THT)
  const padTemplates: Record<string, PadInfo[]> = {
    // 0402 (1005 metric): pad_span=1.0mm, pad=0.6×0.5mm
    '0402': [
      { number: '1', x_nm: -500_000, y_nm: 0, width_nm: 600_000, height_nm: 500_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '2', x_nm:  500_000, y_nm: 0, width_nm: 600_000, height_nm: 500_000, shape: 'rect', layer_mask: 1, drill_nm: null },
    ],
    // 0603 (1608 metric): pad_span=1.6mm, pad=0.9×0.95mm
    '0603': [
      { number: '1', x_nm: -800_000, y_nm: 0, width_nm: 900_000, height_nm: 950_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '2', x_nm:  800_000, y_nm: 0, width_nm: 900_000, height_nm: 950_000, shape: 'rect', layer_mask: 1, drill_nm: null },
    ],
    // 0805 (2012 metric): pad_span=1.9mm, pad=1.0×1.45mm
    '0805': [
      { number: '1', x_nm: -950_000, y_nm: 0, width_nm: 1_000_000, height_nm: 1_450_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '2', x_nm:  950_000, y_nm: 0, width_nm: 1_000_000, height_nm: 1_450_000, shape: 'rect', layer_mask: 1, drill_nm: null },
    ],
    // 1206 (3216 metric): pad_span=3.4mm, pad=1.15×1.8mm
    '1206': [
      { number: '1', x_nm: -1_700_000, y_nm: 0, width_nm: 1_150_000, height_nm: 1_800_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '2', x_nm:  1_700_000, y_nm: 0, width_nm: 1_150_000, height_nm: 1_800_000, shape: 'rect', layer_mask: 1, drill_nm: null },
    ],
    // PIN-HDR-1x2: 100mil (2.54mm) pitch, drill=1.0mm, pad=1.7mm
    // Pin 1 square (rect), Pin 2 round (circle)
    'PIN-HDR-1x2': [
      { number: '1', x_nm: -1_270_000, y_nm: 0, width_nm: 1_700_000, height_nm: 1_700_000, shape: 'rect',   layer_mask: 3, drill_nm: 1_000_000 },
      { number: '2', x_nm:  1_270_000, y_nm: 0, width_nm: 1_700_000, height_nm: 1_700_000, shape: 'circle', layer_mask: 3, drill_nm: 1_000_000 },
    ],
    // SOIC-8: row_span=5.4mm (half=2.7mm), pitch=1.27mm, pad=1.5×0.6mm
    // Pins 1-4 left side (bottom→top), pins 5-8 right side (bottom→top)
    'SOIC-8': [
      { number: '1', x_nm: -2_700_000, y_nm: -1_905_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '2', x_nm: -2_700_000, y_nm:   -635_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '3', x_nm: -2_700_000, y_nm:    635_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '4', x_nm: -2_700_000, y_nm:  1_905_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '5', x_nm:  2_700_000, y_nm: -1_905_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '6', x_nm:  2_700_000, y_nm:   -635_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '7', x_nm:  2_700_000, y_nm:    635_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
      { number: '8', x_nm:  2_700_000, y_nm:  1_905_000, width_nm: 1_500_000, height_nm: 600_000, shape: 'rect', layer_mask: 1, drill_nm: null },
    ],
    // DIP-8: 300mil (7.62mm) row spacing, 100mil (2.54mm) pitch, drill=0.8mm, pad=1.6mm
    // Pins 1-4 left side (top→bottom): y = +150, +50, -50, -150 mil
    // Pins 5-8 right side (bottom→top): y = -150, -50, +50, +150 mil
    // layer_mask: 3 = both top and bottom (through-hole)
    'DIP-8': [
      { number: '1', x_nm: -3_810_000, y_nm:  3_810_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
      { number: '2', x_nm: -3_810_000, y_nm:  1_270_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
      { number: '3', x_nm: -3_810_000, y_nm: -1_270_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
      { number: '4', x_nm: -3_810_000, y_nm: -3_810_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
      { number: '5', x_nm:  3_810_000, y_nm: -3_810_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
      { number: '6', x_nm:  3_810_000, y_nm: -1_270_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
      { number: '7', x_nm:  3_810_000, y_nm:  1_270_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
      { number: '8', x_nm:  3_810_000, y_nm:  3_810_000, width_nm: 1_600_000, height_nm: 1_600_000, shape: 'oblong', layer_mask: 3, drill_nm: 800_000 },
    ],
  };

  return padTemplates[footprint] || padTemplates['0402'];
}

/**
 * Parse .cypcb source code into a BoardSnapshot.
 * This is the JavaScript parser used when tree-sitter is not available (WASM mode).
 */
function parseSource(source: string): { snapshot: BoardSnapshot; errors: string[] } {
  const errors: string[] = [];
  const lines = source.split('\n');

  let board: BoardInfo | null = null;
  let currentBoard: BoardInfo | null = null;
  const components: ComponentInfo[] = [];
  const nets: Map<string, NetInfo> = new Map();
  let currentComponent: Partial<ComponentInfo> | null = null;
  let currentNet: { name: string; pins: string[] } | null = null;
  let braceDepth = 0;
  let inBoard = false;
  let inComponent = false;
  let inNet = false;

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum].trim();
    if (!line || line.startsWith('//')) continue;

    // Count braces
    const openBraces = (line.match(/{/g) || []).length;
    const closeBraces = (line.match(/}/g) || []).length;

    // Parse version (ignore)
    if (line.startsWith('version ')) {
      continue;
    }

    // Parse board definition
    const boardMatch = line.match(/^board\s+(\w+)\s*{?$/);
    if (boardMatch) {
      currentBoard = {
        name: boardMatch[1],
        width_nm: 0,
        height_nm: 0,
        layer_count: 2,
      };
      inBoard = true;
      braceDepth += openBraces;
      continue;
    }

    // Parse component definition
    const compMatch = line.match(/^component\s+(\w+)\s+(\w+)\s+"([^"]+)"\s*{?$/);
    if (compMatch) {
      currentComponent = {
        refdes: compMatch[1],
        value: '',
        x_nm: 0,
        y_nm: 0,
        rotation_mdeg: 0,
        footprint: compMatch[3],
        pads: getFootprintPads(compMatch[3]),
      };
      inComponent = true;
      braceDepth += openBraces;
      continue;
    }

    // Parse net definition
    const netMatch = line.match(/^net\s+(\w+)\s*{?$/);
    if (netMatch) {
      currentNet = { name: netMatch[1], pins: [] };
      inNet = true;
      braceDepth += openBraces;
      continue;
    }

    // Parse board properties
    if (inBoard && currentBoard) {
      const sizeMatch = line.match(/^size\s+(\d+(?:\.\d+)?)(mm|mil|inch)\s+x\s+(\d+(?:\.\d+)?)(mm|mil|inch)$/);
      if (sizeMatch) {
        currentBoard.width_nm = parseUnit(parseFloat(sizeMatch[1]), sizeMatch[2]);
        currentBoard.height_nm = parseUnit(parseFloat(sizeMatch[3]), sizeMatch[4]);
      }
      const layersMatch = line.match(/^layers\s+(\d+)$/);
      if (layersMatch) {
        currentBoard.layer_count = parseInt(layersMatch[1], 10);
      }
    }

    // Parse component properties
    if (inComponent && currentComponent) {
      const valueMatch = line.match(/^value\s+"([^"]*)"$/);
      if (valueMatch) {
        currentComponent.value = valueMatch[1];
      }
      const atMatch = line.match(/^at\s+(\d+(?:\.\d+)?)(mm|mil|inch),\s*(\d+(?:\.\d+)?)(mm|mil|inch)(?:\s+rotate\s+(\d+(?:\.\d+)?))?$/);
      if (atMatch) {
        currentComponent.x_nm = parseUnit(parseFloat(atMatch[1]), atMatch[2]);
        currentComponent.y_nm = parseUnit(parseFloat(atMatch[3]), atMatch[4]);
        if (atMatch[5]) {
          currentComponent.rotation_mdeg = Math.round(parseFloat(atMatch[5]) * 1000);
        }
      }
    }

    // Parse net pins
    if (inNet && currentNet) {
      const pinMatch = line.match(/^(\w+)\.(\w+)$/);
      if (pinMatch) {
        currentNet.pins.push(`${pinMatch[1]}.${pinMatch[2]}`);
      }
    }

    // Handle closing braces
    if (closeBraces > 0) {
      braceDepth -= closeBraces;

      if (braceDepth <= 0) {
        if (inBoard && currentBoard) {
          board = currentBoard;
          currentBoard = null;
          inBoard = false;
        }
        if (inComponent && currentComponent) {
          components.push(currentComponent as ComponentInfo);
          currentComponent = null;
          inComponent = false;
        }
        if (inNet && currentNet) {
          const connections: PinRef[] = currentNet.pins.map(pin => {
            const [component, pinNum] = pin.split('.');
            return { component, pin: pinNum };
          });
          nets.set(currentNet.name, {
            name: currentNet.name,
            id: nets.size,
            connections,
          });
          currentNet = null;
          inNet = false;
        }
        braceDepth = 0;
      }
    }

    braceDepth += openBraces;
  }

  return {
    snapshot: { board, components, nets: Array.from(nets.values()), violations: [], traces: [], vias: [], ratsnest: [] },
    errors,
  };
}

/**
 * Parse FreeRouting .ses (session) file to extract routing results.
 * Returns traces and vias that can be added to a BoardSnapshot.
 */
export function parseSesFile(sesContent: string): { traces: BoardSnapshot['traces']; vias: BoardSnapshot['vias'] } {
  const traces: BoardSnapshot['traces'] = [];
  const vias: BoardSnapshot['vias'] = [];

  // Default resolution: mil 10 = 1/10 mil = 2540 nm
  let resolution = 2540; // nm per unit

  // Parse resolution from routes section
  const resMatch = sesContent.match(/\(routes[\s\S]*?\(resolution\s+(\w+)\s+(\d+)\)/);
  if (resMatch) {
    const unit = resMatch[1];
    const divisor = parseInt(resMatch[2], 10);
    if (unit === 'mil') {
      resolution = Math.round(25400 / divisor); // 1 mil = 25400 nm
    } else if (unit === 'mm') {
      resolution = Math.round(1_000_000 / divisor);
    }
  }
  console.log('[SES Parser] Resolution:', resolution, 'nm per unit');

  // Find network_out content
  const networkOutStart = sesContent.indexOf('(network_out');
  if (networkOutStart === -1) {
    console.log('[SES Parser] No network_out section found');
    return { traces, vias };
  }
  const networkSection = sesContent.slice(networkOutStart);

  // Find net blocks by counting parentheses (more reliable than regex)
  let pos = 0;
  while (true) {
    const netStart = networkSection.indexOf('(net ', pos);
    if (netStart === -1) break;

    // Find net name
    const nameMatch = networkSection.slice(netStart).match(/\(net\s+(\w+)/);
    if (!nameMatch) break;
    const netName = nameMatch[1];

    // Find where this net ends by counting parentheses
    let depth = 0;
    let netEnd = netStart;
    for (let i = netStart; i < networkSection.length; i++) {
      if (networkSection[i] === '(') depth++;
      if (networkSection[i] === ')') depth--;
      if (depth === 0) {
        netEnd = i + 1;
        break;
      }
    }

    const netContent = networkSection.slice(netStart, netEnd);
    pos = netEnd;

    // Find all wire paths in this net
    const wirePathRegex = /\(path\s+(\S+)\s+(\d+)\s+([\d\s\-]+)\)/g;
    let pathMatch;

    while ((pathMatch = wirePathRegex.exec(netContent)) !== null) {
      const layerStr = pathMatch[1];
      const width = parseInt(pathMatch[2], 10) * resolution;
      const coordsStr = pathMatch[3].trim();
      const coords = coordsStr.split(/\s+/).map(s => parseInt(s, 10));

      // Convert layer name (F.Cu -> Top, B.Cu -> Bottom)
      const layer = layerStr === 'B.Cu' ? 'Bottom' : 'Top';

      // Create segments from coordinate pairs
      const segments: { start_x: number; start_y: number; end_x: number; end_y: number }[] = [];
      for (let i = 0; i < coords.length - 2; i += 2) {
        segments.push({
          start_x: coords[i] * resolution,
          start_y: coords[i + 1] * resolution,
          end_x: coords[i + 2] * resolution,
          end_y: coords[i + 3] * resolution,
        });
      }

      if (segments.length > 0) {
        traces.push({
          id: traces.length,
          segments,
          width,
          layer,
          net_name: netName,
          locked: false,
        });
      }
    }

    // Find vias in this net
    const viaRegex = /\(via\s+\w+\s+(\d+)\s+(\d+)\)/g;
    let viaMatch;
    while ((viaMatch = viaRegex.exec(netContent)) !== null) {
      vias.push({
        id: vias.length,
        x: parseInt(viaMatch[1], 10) * resolution,
        y: parseInt(viaMatch[2], 10) * resolution,
        drill: 300_000,
        outer_diameter: 600_000,
        net_name: netName,
      });
    }
  }

  console.log('[SES Parser] Parsed', traces.length, 'traces,', vias.length, 'vias');
  return { traces, vias };
}

// ============================================================================
// Geometry utilities (used by MockPcbEngine hit-testing and DRC)
// ============================================================================

/**
 * Shortest distance from point (px,py) to line segment (ax,ay)-(bx,by).
 */
function pointToSegmentDistance(
  px: number, py: number,
  ax: number, ay: number,
  bx: number, by: number,
): number {
  const dx = bx - ax;
  const dy = by - ay;
  const lenSq = dx * dx + dy * dy;
  if (lenSq === 0) {
    const ex = px - ax;
    const ey = py - ay;
    return Math.sqrt(ex * ex + ey * ey);
  }
  let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
  t = Math.max(0, Math.min(1, t));
  const cx = ax + t * dx;
  const cy = ay + t * dy;
  const ex = px - cx;
  const ey = py - cy;
  return Math.sqrt(ex * ex + ey * ey);
}

/**
 * Approximate minimum distance between two line segments.
 * Tests endpoints of each segment against the other segment.
 */
function segmentToSegmentDistance(
  s1: TraceSegmentInfo,
  s2: TraceSegmentInfo,
): number {
  // Sample several points: endpoints + midpoints, take minimum
  const d1 = pointToSegmentDistance(s1.start_x, s1.start_y, s2.start_x, s2.start_y, s2.end_x, s2.end_y);
  const d2 = pointToSegmentDistance(s1.end_x, s1.end_y, s2.start_x, s2.start_y, s2.end_x, s2.end_y);
  const d3 = pointToSegmentDistance(s2.start_x, s2.start_y, s1.start_x, s1.start_y, s1.end_x, s1.end_y);
  const d4 = pointToSegmentDistance(s2.end_x, s2.end_y, s1.start_x, s1.start_y, s1.end_x, s1.end_y);
  return Math.min(d1, d2, d3, d4);
}

// ============================================================================
// WASM Engine Adapter
// ============================================================================

/**
 * Adapter that wraps the raw WASM PcbEngine and provides the load_source() method.
 *
 * The WASM engine doesn't include tree-sitter, so parsing is done in JavaScript.
 * This adapter parses the source, then calls load_snapshot() on the WASM engine.
 * Query operations use the WASM engine's spatial index for efficiency.
 */
class WasmPcbEngineAdapter implements PcbEngine {
  private wasmEngine: WasmPcbEngine;
  private cachedSnapshot: BoardSnapshot | null = null;

  constructor(wasmEngine: WasmPcbEngine) {
    this.wasmEngine = wasmEngine;
  }

  load_source(source: string): string {
    // Parse in JavaScript
    const { snapshot, errors } = parseSource(source);

    // Cache snapshot (traces/vias/ratsnest will be populated by load_routes)
    this.cachedSnapshot = snapshot;

    // Store snapshot and load into WASM engine for queries
    const wasmError = this.wasmEngine.load_snapshot(snapshot);
    if (wasmError) {
      errors.push(wasmError);
    }

    return errors.join('\n');
  }

  load_routes(sesContent: string): void {
    if (!this.cachedSnapshot) return;

    // Parse .ses file and extract routes
    const { traces, vias } = parseSesFile(sesContent);

    // Replace traces and vias in cached snapshot
    this.cachedSnapshot.traces = traces;
    this.cachedSnapshot.vias = vias;

    // Build set of routed connections (net + pin)
    const routedPins = new Set<string>();
    for (const trace of traces) {
      if (trace.net_name) {
        // For each net, we consider all pins in that net as "connected" if there are traces
        const net = this.cachedSnapshot.nets.find(n => n.name === trace.net_name);
        if (net) {
          for (const conn of net.connections) {
            routedPins.add(`${conn.component}.${conn.pin}`);
          }
        }
      }
    }

    // Regenerate ratsnest only for unrouted connections
    this.cachedSnapshot.ratsnest = [];
    for (const net of this.cachedSnapshot.nets) {
      if (net.connections.length < 2) continue;

      // Check if this net has any traces
      const hasTraces = traces.some(t => t.net_name === net.name);
      if (hasTraces) continue; // Skip routed nets

      // Get pin positions for unrouted net
      const positions: { x: number; y: number }[] = [];
      for (const conn of net.connections) {
        const comp = this.cachedSnapshot.components.find(c => c.refdes === conn.component);
        if (comp) {
          const pad = comp.pads.find(p => p.number === conn.pin);
          positions.push({
            x: comp.x_nm + (pad?.x_nm ?? 0),
            y: comp.y_nm + (pad?.y_nm ?? 0),
          });
        }
      }

      // Create star-topology ratsnest
      if (positions.length >= 2) {
        for (let i = 1; i < positions.length; i++) {
          this.cachedSnapshot.ratsnest.push({
            start_x: positions[0].x,
            start_y: positions[0].y,
            end_x: positions[i].x,
            end_y: positions[i].y,
            net_name: net.name,
          });
        }
      }
    }
  }

  get_snapshot(): BoardSnapshot {
    // Return cached snapshot with traces/ratsnest that we added in JS
    // The WASM engine's get_snapshot() would have empty traces since
    // we only populated components/board, not Trace entities
    if (this.cachedSnapshot) {
      // Get DRC violations from WASM (computed in Rust)
      const wasmSnapshot = this.wasmEngine.get_snapshot();
      return {
        ...this.cachedSnapshot,
        violations: wasmSnapshot.violations || [],
      };
    }
    return this.wasmEngine.get_snapshot();
  }

  query_point(x_nm: number, y_nm: number): string[] {
    // Use WASM spatial index for efficient queries
    // The WASM engine rebuilds the spatial index in populate_from_snapshot()
    return this.wasmEngine.query_point(BigInt(x_nm), BigInt(y_nm));
  }

  add_trace(net_name: string, layer: string, width_nm: number, segments: number[]): number {
    const id = this.wasmEngine.add_trace_json(net_name, layer, BigInt(width_nm), JSON.stringify(segments));
    // Invalidate cached snapshot so next get_snapshot() picks up the new trace
    this.cachedSnapshot = null;
    return id;
  }

  remove_trace(trace_id: number): boolean {
    const removed = this.wasmEngine.remove_trace(trace_id);
    if (removed) {
      this.cachedSnapshot = null;
    }
    return removed;
  }

  get_trace_at_point(x_nm: number, y_nm: number, tolerance_nm: number): number {
    return this.wasmEngine.get_trace_at_point(BigInt(x_nm), BigInt(y_nm), BigInt(tolerance_nm));
  }

  run_drc_incremental(): number {
    return this.wasmEngine.run_drc_incremental();
  }

  trace_count(): number {
    return this.wasmEngine.trace_count();
  }

  free(): void {
    this.wasmEngine.free();
  }
}

// ============================================================================
// Mock Engine (fallback when WASM is unavailable)
// ============================================================================

/**
 * Mock PCB engine for development/testing without WASM.
 * Uses the same JavaScript parser as the WASM adapter.
 */
class MockPcbEngine implements PcbEngine {
  private snapshot: BoardSnapshot = { board: null, components: [], nets: [], violations: [], traces: [], vias: [], ratsnest: [] };
  /** Next mock entity ID counter */
  private nextEntityId = 1000;

  load_source(source: string): string {
    const { snapshot, errors } = parseSource(source);
    this.snapshot = snapshot;
    return errors.join('\n');
  }

  load_routes(sesContent: string): void {
    // Parse .ses file and extract routes
    const { traces, vias } = parseSesFile(sesContent);

    // Replace traces and vias
    this.snapshot.traces = traces;
    this.snapshot.vias = vias;

    // Regenerate ratsnest only for unrouted nets
    this.snapshot.ratsnest = [];
    for (const net of this.snapshot.nets) {
      if (net.connections.length < 2) continue;

      // Skip nets that have traces
      const hasTraces = traces.some(t => t.net_name === net.name);
      if (hasTraces) continue;

      // Get pin positions for unrouted net
      const positions: { x: number; y: number }[] = [];
      for (const conn of net.connections) {
        const comp = this.snapshot.components.find(c => c.refdes === conn.component);
        if (comp) {
          const pad = comp.pads.find(p => p.number === conn.pin);
          positions.push({
            x: comp.x_nm + (pad?.x_nm ?? 0),
            y: comp.y_nm + (pad?.y_nm ?? 0),
          });
        }
      }

      // Create star-topology ratsnest
      if (positions.length >= 2) {
        for (let i = 1; i < positions.length; i++) {
          this.snapshot.ratsnest.push({
            start_x: positions[0].x,
            start_y: positions[0].y,
            end_x: positions[i].x,
            end_y: positions[i].y,
            net_name: net.name,
          });
        }
      }
    }
  }

  get_snapshot(): BoardSnapshot {
    return this.snapshot;
  }

  query_point(x_nm: number, y_nm: number): string[] {
    const result: string[] = [];

    for (const comp of this.snapshot.components) {
      // Check if point is within component bounds (simplified)
      const compWidth = 2_000_000; // 2mm default
      const compHeight = 1_000_000; // 1mm default

      if (x_nm >= comp.x_nm - compWidth / 2 &&
          x_nm <= comp.x_nm + compWidth / 2 &&
          y_nm >= comp.y_nm - compHeight / 2 &&
          y_nm <= comp.y_nm + compHeight / 2) {
        result.push(comp.refdes);
      }
    }

    return result;
  }

  // -- Trace mutation API (MockPcbEngine) --

  add_trace(net_name: string, layer: string, width_nm: number, segments: number[]): number {
    // Validate inputs
    if (segments.length < 4 || segments.length % 4 !== 0) {
      return 0xFFFFFFFF;
    }
    const validLayers = ['Top', 'TopCopper', 'Bottom', 'BottomCopper'];
    const isInner = /^Inner\d+$/.test(layer);
    if (!validLayers.includes(layer) && !isInner) {
      return 0xFFFFFFFF;
    }

    const id = this.nextEntityId++;
    const traceSegments: TraceSegmentInfo[] = [];
    for (let i = 0; i < segments.length; i += 4) {
      traceSegments.push({
        start_x: segments[i],
        start_y: segments[i + 1],
        end_x: segments[i + 2],
        end_y: segments[i + 3],
      });
    }

    // Normalize layer name
    const normalizedLayer = layer === 'TopCopper' ? 'Top' : layer === 'BottomCopper' ? 'Bottom' : layer;

    this.snapshot.traces.push({
      id,
      segments: traceSegments,
      width: width_nm,
      layer: normalizedLayer,
      net_name,
      locked: false,
    });

    console.log(`[MockEngine] add_trace: net=${net_name} layer=${normalizedLayer} id=${id} segs=${traceSegments.length}`);
    return id;
  }

  remove_trace(trace_id: number): boolean {
    const idx = this.snapshot.traces.findIndex(t => t.id === trace_id);
    if (idx === -1) return false;
    this.snapshot.traces.splice(idx, 1);
    console.log(`[MockEngine] remove_trace: id=${trace_id}`);
    return true;
  }

  get_trace_at_point(x_nm: number, y_nm: number, tolerance_nm: number): number {
    let bestId = 0xFFFFFFFF;
    let bestDist = Infinity;

    for (const trace of this.snapshot.traces) {
      const halfWidth = trace.width / 2;
      for (const seg of trace.segments) {
        const dist = pointToSegmentDistance(
          x_nm, y_nm,
          seg.start_x, seg.start_y,
          seg.end_x, seg.end_y,
        );
        if (dist <= halfWidth + tolerance_nm && dist < bestDist) {
          bestDist = dist;
          bestId = trace.id;
        }
      }
    }

    return bestId;
  }

  run_drc_incremental(): number {
    // Mock: simple clearance check between traces
    // Real DRC is in Rust — this just provides a realistic interface
    const violations: ViolationInfo[] = [];
    const MIN_CLEARANCE = 150_000; // 0.15mm in nm

    for (let i = 0; i < this.snapshot.traces.length; i++) {
      for (let j = i + 1; j < this.snapshot.traces.length; j++) {
        const t1 = this.snapshot.traces[i];
        const t2 = this.snapshot.traces[j];
        if (t1.net_name === t2.net_name) continue; // Same net is fine
        if (t1.layer !== t2.layer) continue; // Different layers don't interact

        for (const s1 of t1.segments) {
          for (const s2 of t2.segments) {
            const dist = segmentToSegmentDistance(s1, s2);
            const required = t1.width / 2 + t2.width / 2 + MIN_CLEARANCE;
            if (dist < required) {
              const mx = (s1.start_x + s1.end_x + s2.start_x + s2.end_x) / 4;
              const my = (s1.start_y + s1.end_y + s2.start_y + s2.end_y) / 4;
              violations.push({
                kind: 'clearance',
                x_nm: mx,
                y_nm: my,
                message: `Clearance violation between ${t1.net_name} and ${t2.net_name}: ${(dist / 1_000_000).toFixed(2)}mm < ${(required / 1_000_000).toFixed(2)}mm required`,
              });
            }
          }
        }
      }
    }

    this.snapshot.violations = violations;
    console.log(`[MockEngine] run_drc_incremental: ${violations.length} violations`);
    return violations.length;
  }

  trace_count(): number {
    return this.snapshot.traces.length;
  }
}

// ============================================================================
// Module loading
// ============================================================================

/**
 * Load the WASM module and return the PCB engine instance.
 * Falls back to mock implementation if WASM is not available.
 *
 * @returns The PCB engine instance
 */
export async function loadWasm(): Promise<PcbEngine> {
  if (engineInstance) {
    return engineInstance;
  }

  // Try to load the real WASM module first
  try {
    // Direct import - Vite will handle bundling with vite-plugin-wasm
    const wasm = await import('../pkg/cypcb_render.js');
    await wasm.default();
    wasmModule = wasm;

    // Wrap the WASM engine with our adapter that provides load_source()
    const rawEngine = new wasm.PcbEngine() as unknown as WasmPcbEngine;
    engineInstance = new WasmPcbEngineAdapter(rawEngine);
    console.log('WASM module loaded successfully');
    return engineInstance;
  } catch (e) {
    console.log('WASM not available, using mock:', e);
  }

  // Fallback to MockPcbEngine when:
  // - Development without WASM build
  // - Environments where WASM fails to load
  // - Testing without the Rust backend
  console.log('Using MockPcbEngine (WASM fallback)');
  engineInstance = new MockPcbEngine();
  return engineInstance;
}

/**
 * Get the current engine instance (if loaded)
 */
export function getEngine(): PcbEngine | null {
  return engineInstance;
}

/**
 * Helper to load source and get snapshot in one call
 */
export function loadAndSnapshot(source: string): { snapshot: BoardSnapshot; errors: string } | null {
  if (!engineInstance) return null;

  const errors = engineInstance.load_source(source);
  const snapshot = engineInstance.get_snapshot();

  return { snapshot, errors };
}

/**
 * Check if the engine is using the real WASM implementation
 */
export function isWasmLoaded(): boolean {
  return wasmModule !== null;
}

